/* Evolvlings: English text for the era 2 path conversations (parallel to events-era2.js). */
window.EVEVENTS_EN = window.EVEVENTS_EN || {};
(function (E) {
  const add = (zone, evs) => { E[zone] = Object.assign(E[zone] || {}, evs); };

  add("aurora", {
    "e2-ley": { who: { cirio: "Cirio, notice-board warden", umbria: "Umbría" }, nodes: {
      a: { say: ["The Ford's notice board has a new paper, nailed up with four nails instead of one. A young warden guards it with his arms crossed. At the top, in big letters: THE LAW OF RETURN.",
                 "Read it out loud if you like, nobody else comes near it today. My name's Cirio, and I'm to look after it until the ink dries.",
                 "Behind you, a Shadow woman holding two children by the hand waits for you to step aside so she can read it herself."],
           opts: ["Read the decree", "“What happens if someone doesn't go back?”", "Talk to the woman with the children", "Sign as a witness, as the foot of the paper asks", "Tear the decree off the board", "Leave without a word"] },
      leer: { say: ["“The Underside is cured. The families of the Night will return to their lands before the first frost. The Seven Houses will pay for the journey. Whoever does not return will lose their Threshold permit.”",
                    "At the foot, a line for witnesses. Forty signatures already. Nearly all of them from Meadow folk.",
                    "They say there's no sap down there anymore. That it's all clean. I've never been down, but the Houses say so."] },
      si: { say: ["They lose the permit. No permit, no crossing the Threshold, and no crossing, no work in the Meadow.",
                  "It isn't cruelty, Caretaker. It's that we don't fit here anymore. My sister's been sleeping in the kitchen since they gave her room to a family from the Hollow.",
                  "He says it without looking at the woman with the children, who hears every word."] },
      madre: { say: ["My name is Umbría. Don't mind the warden, he's not a bad man. He just repeats.",
                     "My husband went down to see the Hollow last week. He says it's clean, yes. And that the mist doesn't breathe. That the houses cast no shade. That he touched the wall of ours and it was warm, like an animal that died not long ago.",
                     "The children were born up here. For them the Underside is a story. How do you go back to a story?"],
               opts: ["“You can stay at my house in the Ford.”", "“What do you need for the journey?”", "Go back to the board"] },
      viaje: { say: ["Nothing you have. The Houses pay for the cart, the blanket and three days of bread. Very generous.",
                     "What they don't pay for is the way back, if you can't live down there. That's not on the paper."] },
      firmar: { say: ["You sign below the other forty. Cirio blows on the ink very carefully, as if it mattered that it didn't run.",
                      "Thank you. When a Caretaker signs, people believe it more.",
                      "When you turn around, Umbría has already gone with the children. In the mud, the prints of all three lead towards the gate."] },
      arrancar: { say: ["You pull at the paper. The four nails hold and the decree tears down the middle, with a sound the whole square hears.",
                        "What are you doing? The matriarch signed that!",
                        "Cirio calls the wardens. Tomorrow there'll be another paper, with eight nails. But today the board holds only the bottom half: forty signatures with nothing above them."] },
      esconder: { say: ["Umbría looks at you for a long time. Then she says something to the children in the Court's tongue, and the smallest hides behind her.",
                        "I won't thank you yet. First let's see whether the Houses come looking for us.",
                        "But if they don't, the Quarter will hear that in the Ford there's a door that opens. And that, Caretaker, is worth more than your house."] },
      irte: { say: ["A while later, from far off, you see Umbría reading the paper with one finger, word by word, while the smallest tugs at her skirt."] },
    } },

    "e2-coro": { who: { nim: "Nim", tila: "Tila", capataz: "Choir mistress" }, nodes: {
      a: { say: ["In the Dim Quarter they've built a stage under the last lantern. On it, in pairs, Light children and Shadow children sing in turns. A choir mistress beats time with a rod. Each time a pair finishes, the lantern shines a little brighter.",
                 "Together! Both lullabies at once, like in the Ford! The matriarch wants light for the whole Quarter before winter.",
                 "In the third pair, singing with a Light girl he doesn't know, is Nim. He sings well. He looks at no one."],
           opts: ["Listen to how it sounds", "Look for Tila in the crowd", "Get up on the stage and sing with them", "Sing off-key on purpose, very loudly", "Wait for Nim to come down and take him away"] },
      suena: { say: ["It sounds pretty and it sounds like nothing. The two lullabies go together, note for note, but every child looks the other way. The sap doesn't pull back an inch.",
                     "At the foot of the stage, on a rag, lie three little bright things the size of a fist. They're Stars. They make no sound. One has already gone out completely.",
                     "They come out on their own, sometimes. They're no use. They go out in two or three days."] },
      tila: { say: ["Here I am, watching them copy me. When Nim and I did it, it was because we wanted to. This is a line of kids paid half a ration to sing.",
                    "I told the matriarch. She said I was the proof that it worked. That thanks to me the Quarter would have light. And the worst part is she meant it.",
                    "Look at those Stars. That's what a promise nobody wanted to make sounds like."] },
      cantar: { say: ["The mistress puts you beside a Shadow boy who's trembling a little. You sing. The lantern shines. Everyone claps.",
                      "A new Star falls at your feet, the size of a walnut. It looks at you without a mouth. It shines three seconds longer than the others and goes still.",
                      "Come back tomorrow! With a Caretaker on the stage, the Quarter sings twice as much."] },
      sabotear: { say: ["You push in among the pairs and sing loud and badly. One pair laughs, another stops. The mistress strikes the stage with her rod.",
                        "Out! Wardens!",
                        "Nim uses the commotion to get off the stage. Passing you, without looking, he says very quietly: “Thanks. I'll be back tomorrow anyway. It pays.”"] },
      sacar: { say: ["When Nim's pair finishes, you wait for him at the foot of the stage. He's pale, as if he'd sung with someone else's throat.",
                     "Don't take me out of here like a child, I'm not one. I sing because my mother eats from what they pay me.",
                     "But if you really want to help, take that.",
                     "He points at the smallest Star on the rag, the one that still glows a little. Unísona looks at it and sings a single note. The Star moves."],
               opts: ["Take the Star", "Take Nim, even if he protests"] },
      estrella: { say: ["You wrap it in your scarf. It weighs nothing. Unísona walks beside you all the way back, watching it, the way you watch a sick little brother.",
                        "Give it a name. The ones with names find it harder to go out. My mother used to say that about children, and I think it goes for everything."] },
      nimlejos: { say: ["If you take me, tomorrow they'll put someone else up. Someone smaller, who sings worse and gets paid less.",
                        "But he comes down with you. At the Quarter's door he stops, looks at the stage and sings alone, softly, his whole lullaby. Nobody pays him. The lantern doesn't shine any brighter.",
                        "That one was for me."] },
    } },

    "e2-velada": { who: { destello: "Lucerna Destello", alvar: "Alvar" }, nodes: {
      a: { say: ["It's the longest night of the year. Every House in the Meadow lights all its lanterns at once. The sky turns white. There's music, sweet bread and people dancing in the squares.",
                 "On the balcony of the Tower of Dawn, a young woman with her hair tied back and a plain dress waves to the crowd. She wears no jewels. The Quarter folk cheer her louder than anyone.",
                 "That's the new matriarch. Lucerna Destello. She was born in the Dim Quarter, did you know? The first one who isn't from an old House.",
                 "Alvar has grown. His boots are caked in mud and he doesn't seem to mind."],
           opts: ["“And your grandmother?”", "Look at the ground of the square", "Climb to the balcony to talk to the matriarch", "Break the big lantern in the square", "Dance with the crowd"] },
      abuela: { say: ["They pushed her aside. Because of the tubes, they say. She says she deserved it, and then spends the afternoon giving orders to the flowerpots.",
                      "She didn't come today. She said a Night of Lanterns with every lantern lit frightened her. That her grandmother told her something about a debt you don't pay to the sun. I didn't understand."] },
      suelo: { say: ["Between the stones of the square, in the cracks, there's something dark. At first it looks like shadow. Then you see it moving, slowly, like water rising.",
                     "You crouch down. It smells of wet earth and of something sweet and rotten. Under the feet of the dancers, the clear sap is turning black."] },
      balcon: { say: ["The Caretaker. Come in, come in, tonight the Tower belongs to everyone.",
                      "See that? A year ago, on my street, one lantern in three was lit. Tonight there isn't a single dark door in the Quarter. We did that, not Albor."],
                opts: ["“The sap is rising through the square.”", "“Where does so much light come from?”", "“Congratulations.”"] },
      donde: { say: ["From below, as always. The difference is that now it reaches everyone.",
                     "I know what you're going to say, Caretaker. That Albor drank from the Root. I know. That's why we dig deeper, where it bothers nobody. My engineers checked."] },
      aviso: { say: ["Destello looks down at the square. For a moment her smile fades. Then it comes back.",
                     "It's the shadow of so many people dancing. Not tonight, Caretaker. Tonight the Quarter has light. Tomorrow we look at the ground, I promise.",
                     "I saw it too. If you want, tomorrow I'll tell the old Houses. They still open the door to me."],
               opts: ["“Do it, Alvar. Let every House know.”", "Leave it for tomorrow"] },
      alvarsi: { say: ["First thing tomorrow. Even if they throw me out. I've been thrown out of worse.",
                       "Below, without anyone else noticing, the last crack in the square turns black."] },
      manana: { say: ["The next morning, the Meadow wakes to black stains in every square. The Houses say it was Shadow sabotage."] },
      felicidades: { say: ["Thank you. Really. You're one of the few who says it without asking me for something in return.",
                           "From the balcony, the square looks beautiful. From up here you can't see the ground."] },
      romper: { say: ["You throw a stone at the big lantern. The glass cracks and the light flickers. The music stops. Someone shouts “shadows!” and people draw back from the Quarter folk.",
                      "That's not what you wanted. But in the dark of the broken lantern, under your feet, the ground stops darkening. A hand's breadth. Just a hand's breadth."] },
      bailar: { say: ["You dance until your feet hurt. Your creatures too. It's the best party in years. Nobody looks at the ground, and neither do you."] },
    } },
  });

  add("crater", {
    "e2-tubos": { who: { tizon: "Master Tizón", fogarin: "Fogarín" }, nodes: {
      a: { say: ["In the great forge there are glass tubes everywhere, leaning against the walls like spears. They're three times longer than the ones that left here last year.",
                 "Don't touch them, they're still warm. An order from the new matriarch. Two hundred. Pays in advance, can you believe it? In advance. Albor never paid in advance.",
                 "At the back, a young man with old burns on his arms works the bellows without a word. It's Fogarín, the apprentice. Not so much an apprentice anymore."],
           opts: ["“Why are they so long?”", "Talk to Fogarín", "“Master, these tubes drink from the Root.”", "Break one “by accident”", "Help load the order"] },
      para: { say: ["To reach deeper, she says. Where they won't bother anyone. I didn't ask more. I've had a seat on the Council of Houses for a month, and a Fire with a seat learns fast which questions aren't asked.",
                    "They used to keep me out of the front door. Now they serve me first. Don't ask me to throw that away on a hunch."] },
      fogarin: { say: ["I blow, I don't give opinions. That's what the master taught me.",
                       "But I'll tell you one thing. When a girl from the Water worked here, she told me long glass sings when you cool it. This one doesn't sing. This one sounds like someone swallowing."] },
      decir: { say: ["And who says so? A lake seer? A shadow?",
                     "But he sets the hammer down on the anvil. For a long time.",
                     "My father kept the Night of Embers. He put out every fire in the Crater and lit just one, one night a year. He said it was so the earth could rest. We laughed at him."],
              opts: ["“Keep the Night of Embers this year.”", "“Come to the Heart when I call.”", "Don't press him"] },
      ascuas: { say: ["Put out the Crater for a night, with two hundred tubes to deliver? They'd throw me off the Council before dawn.",
                      "But look, I can deliver a hundred and ninety. Ten break. Happens in every forge. Nobody counts broken glass."] },
      corazon: { say: ["You paid me in full when nobody did. I don't forget that.",
                       "If one day something rings out at the Heart and the Fire has to be there, the Fire will be there. Even if it's just me, with my hammer and my bad knees."] },
      romper: { say: ["You lean where you shouldn't. A tube falls and shatters. Tizón looks at you, red in the face.",
                      "I'm docking that from what I'll never pay you. Out of my forge.",
                      "On your way out, Fogarín catches up and presses a shard of glass into your hand. Inside it runs a black vein, thin as a hair."] },
      cargar: { say: ["You load tubes all afternoon. Tizón pays you in new coins, stamped with Destello's seal. They weigh more than Albor's."] },
    } },

    "e2-brida": { who: { brida: "Brida, forewoman" }, nodes: {
      a: { say: ["In the baths square, a Shadow woman in a miner's helmet writes names on a board. A line of Crater workers waits their turn. The board says: DIGGERS WANTED. DOUBLE PAY. NO ONE ASKS WHERE YOU'RE FROM.",
                 "Here to work? You've got working hands. Here everyone has a name, Caretaker. Mine's Brida. I earned it."],
           opts: ["“How do you earn a name?”", "“Where's the digging?”", "Put your name on the board", "Warn the people in line about what's down there", "“I'm offering you other work, in the Ford.”"] },
      nombre: { say: ["By working. When we came up from the Hollow, they called us Court folk “the dusty one”, “the one in the third row”. In Albor's Wells nobody said our names, and neither did we: the King forbade it.",
                      "The new matriarch asked me what my name was. The first person from up here who ever asked. I told her one I'd made up that same morning. She wrote it down as if it were real.",
                      "For that woman I'd dig to the bottom of the world."] },
      donde: { say: ["Under the Meadow, deeper than Albor. New wells. They call them blind because they have no mouth up top: you get in through tunnels from far away, so nobody sees them.",
                     "Why so hidden? So nobody sabotages them. Someone already broke lanterns on the Night of Lanterns."] },
      apuntar: { say: ["Good. Tomorrow at the ash hour, at the mouth of the south tunnel. Bring water. It's strangely hot down there, like an animal.",
                       "She gives you a wooden token with a number. Yours is 312."] },
      avisar: { say: ["You climb onto the edge of a fountain and tell them what you know about the Wells and the Root. A few people leave the line. Most stay: the pay is double.",
                      "Very nice. Now explain to their children why they won't eat this week.",
                      "She doesn't shout. She looks at you with her helmet in her hand, the way you look at someone who understood nothing."] },
      otro: { say: ["In the Ford? Looking after what, creatures? How much does that pay?",
                    "I heard you're hiding a Court family. Umbría. I know her: we were neighbours in the Wells. She refused to take a false name.",
                    "Brida goes quiet. She crosses something out on the board. You can't see what.",
                    "I'm not leaving the Wells. But if something happens down there one day, I'll warn you before the matriarch. That much I can do."] },
    } },
  });

  add("forest", {
    "e2-fruta": { who: { liquen: "Grandpa Liquen", llovizna: "Llovizna" }, nodes: {
      a: { say: ["The branches of the Deep Wood bend with fruit. Apples, acorns, blackberries, all at once and out of season. There's so much on the ground that the path smells of wine.",
                 "Caretaker! Look how many! The Council says it's the Clear Sap, that the Root is giving back what we took from it.",
                 "A little further on, sitting on a root, Grandpa Liquen stares at a heavily laden apple tree. He isn't eating."],
           opts: ["Help Llovizna gather fruit", "Sit with the old man", "Cut a branch to see what's inside", "“Grandpa, we have to call the Long Silence.”"] },
      juntar: { say: ["You fill two baskets. The apples are huge and sweet, too sweet. Your creatures eat until they fall asleep.",
                      "This year nobody goes hungry in the Wood!"] },
      liquen: { say: ["This year the wood has given more fruit than ever. That's what frightens me.",
                      "When I was a boy, in the Wood I came from, the same thing happened. An autumn of fruit like this one. The next winter there was nothing left. The trees had eaten the soil to make fruit, like a mother who goes without bread.",
                      "And the Hedge is withering out of season. Look. The thorns I planted to close the way fall off by themselves, with black flowers at the tips."] },
      rama: { say: ["You cut a branch from the apple tree. Outside it's green. Inside, in the heart of the wood, runs a thin black vein, like ink.",
                    "Llovizna covers her mouth. Liquen nods slowly, as if he already knew."] },
      silencio: { say: ["Now? In autumn? The Long Silence is in winter. If I call it early, the Council will say the old man from outside doesn't even know what season he's in.",
                        "Years ago, during a Long Silence, I heard it cough. I told no one. For fear they'd open the Vault. I kept it to myself, and look where we are."],
                  opts: ["“This time, don't keep it to yourself.”", "“Then listen to it on your own.”"] },
      llama: { say: ["Fine. Tomorrow I'll strike the hollow trunk. Let them laugh. The Wood will be quiet for three days, even with fruit rotting on the ground.",
                     "And if one day someone sings at the Heart and the Wood is needed, the Wood will be there. That promise I will keep."] },
      solo: { say: ["Liquen presses his ear to the apple tree. So do you. For a long while there's nothing to hear.",
                    "It isn't coughing. It's breathing deeply, very deeply, like someone sleeping hungry."] },
    } },

    "e2-seto": { who: { abrojo: "Abrojo, Hedge guard" }, nodes: {
      a: { say: ["Where the thorn Hedge used to be, there's now a dry brown wall. On the other side, on the road to the Underside, a line of Law of Return carts waits to be let through.",
                 "The Council sent me to cut a gap. The Houses pay for the displaced to go back this way, it's shorter.",
                 "The odd thing is the Hedge won't let me. I cut one branch and two grow back. Dry, but they grow. As if it didn't want anyone going back this way."],
           opts: ["Help Abrojo open the way", "Talk to the people in the carts", "Touch the Hedge", "Leave the Hedge closed"] },
      carros: { say: ["In the first cart rides an old man of the Tides with an old boat tied on top. There's no water on the road, but he wouldn't leave it.",
                      "“They say the lake is cured,” he tells you. “What I want to know is whether the lake will recognise me.”"] },
      tocar: { say: ["You put your hand on the dry wall. It's warm. Inside, very slowly, something beats. The Hedge's roots went deep, much deeper than Liquen meant, and down there they found something to drink.",
                     "The Hedge isn't a wall. It's an embrace that won't let go."] },
      abrir: { say: ["The two of you cut for hours. At last a gap opens as wide as a cart. The old man with the boat goes through first. He doesn't say thank you. He cries.",
                     "There. The Council will be pleased. The Houses too."] },
      cerrado: { say: ["If I don't open it, the Houses will send their wardens with axes, and they won't be careful with the Hedge.",
                       "But he puts the shears away. The carts turn around, towards the long road. They'll take three more days to reach a place that may not want them."] },
    } },
  });

  add("heights", {
    "e2-bajan": { who: { tormo: "Tormo, pass guard" }, nodes: {
      a: { say: ["Down the Heights road comes a line of people with blankets over their shoulders. Whole families, with kites folded on their backs like broken wings.",
                 "Forty families this week. Without the Lady of the Choir's dealings, nobody eats in the Heights this winter. They come down to the Meadow to beg.",
                 "Two winters ago I closed this pass so the people below couldn't come up. Now I open it so the people above can come down. With the same blanket."],
           opts: ["Share food among the families", "“Why did the dealings break down?”", "Show them the way to the Ford", "Keep climbing without stopping"] },
      tratos: { say: ["Because someone sang in the square that the exodus storm never happened. That the Lady lied to close the passes.",
                      "It was true. I was at the pass that week. Clear sky. But now nobody trusts the Choir, nobody sells anything to the Heights, and these are the ones who pay."] },
      comida: { say: ["You share bread and fruit from the Wood among the children. A girl with a red kite gives you a blue feather in return.",
                      "“So the wind can find you,” she says. It's what they say in the Heights when there's nothing else to give."] },
      vado: { say: ["You explain how to reach the Ford. Some of them exchange uneasy looks. “Is there no Law of Return there?” a man asks.",
                    "You don't know what to tell him."] },
      seguir: { say: ["You climb against the stream of people. Nobody asks you for anything. In the Heights you don't ask; you wait."] },
    } },

    "e2-cefira": { who: { cefira: "Céfira", arpegio: "Arpegio" }, nodes: {
      a: { say: ["In the Choir hall there are three chairs. One is empty. In another, a barefoot old man watches a woman's mouth to read her lips. The woman, in the third, says nothing. She hasn't said anything in public for a year.",
                 "You talk, she answers you. Me she only looks at now. Since the trial everyone knows I can't hear, and she can't stand that I know she knows."],
           opts: ["“Céfira, your people are coming down to beg.”", "“Why did you lie about the storm?”", "Speak to her with your hands, as Arpegio does", "Leave her in peace"] },
      mintio: { say: ["Because there wasn't food for everyone. If I let the second wave come up, the Heights would eat half for one winter, and the next one nobody would eat.",
                      "I closed the passes and said “storm”, which is easier to forgive than “there's no room”. People died below. I know. I count them every night.",
                      "It's the first thing she's said in a year. Arpegio leans forward to read it."] },
      pueblo: { say: ["I know. I see them from the window. My silence is all they have left: if I speak, the Meadow hears the liar of the exodus, and they close the door on them too."],
                opts: ["“Speak in the square. Tell the truth, and ask.”", "“Then stay silent.”"] },
      manos: { say: ["You make with your hands the little you learned from Arpegio: “I”, “listen”, “you”. Céfira laughs for the first time, a short, broken laugh.",
                     "You told her “I listen to you”. Nobody in the Choir has said that to her in forty years."] },
      plaza: { say: ["Ask? The Heights never ask. We share verses, we carry messages. We don't ask.",
                     "I can ask. They've already lost their respect for me. There's nothing to lose.",
                     "Céfira looks at the old man for a long time. Then she stands up.",
                     "I'll go down to the Meadow. I'll tell the truth and ask, the two of us together. And if the Heart ever calls the nine peoples, the Heights will go. This once, without selling anything."] },
      callada: { say: ["Céfira turns back to the window. Arpegio sighs and walks you to the door.",
                       "Keeping quiet is also a way of lying. I know that better than anyone."] },
      paz: { say: ["On your way out you hear Arpegio humming a song without sound. He knows the melody by heart. He never heard it."] },
    } },
  });

  add("hollow", {
    "e2-vuelta": { who: { calina: "Calina, mist weaver" }, nodes: {
      a: { say: ["The Hollow is clean. No sap in the cracks, no smell of fever. No mist either. The Court's houses, made for living in half-light, stand bare under a grey sky, like shorn animals.",
                 "We came back because of the Law. Twenty families. I've spent three days trying to weave mist and nothing comes. The Hollow doesn't breathe.",
                 "Calina's hands are full of grey threads that come apart when touched."],
           opts: ["“What does the mist need to come out?”", "Help her weave", "Sing the Shadow lullaby in the middle of the valley", "“Go back to the Meadow. This is no life.”"] },
      niebla: { say: ["It used to come out by itself, from the ground. The Root breathed below and the Hollow filled with its breath. We only combed it.",
                      "Now the Root sleeps so deep it doesn't breathe. They told us the Underside was cured. It's cured the way a dead man is cured: nothing hurts anymore."] },
      tejer: { say: ["You spend the afternoon with the threads. No mist comes, but by nightfall Calina manages a small veil, the size of a handkerchief, for her granddaughter's cradle.",
                     "It's not much. But it's the first thing we've made here since we came back."] },
      cantar: { say: ["In the middle of the valley you sing the lullaby Nim taught you. Unísona sings the other half with you, the Light half.",
                      "From the ground rises one strand of mist, just one, thin as a sigh. All twenty families come out of their houses to watch it. Nobody speaks until it fades.",
                      "It breathes. A little, but it breathes. If one day there's singing at the Heart, the Court has to be there. I'll see that we are."] },
      volver: { say: ["To the Meadow? Without a Threshold permit? We have no door up there anymore, Caretaker. The Law left us without a place on either side."] },
    } },

    "e2-nombres": { who: { ceniza: "Ceniza", lobrego: "King Lóbrego" }, nodes: {
      a: { say: ["In an empty house in the Hollow, behind a curtain, a Shadow girl hides with her hood pulled low. When she sees you, she shrinks back.",
                 "Don't say my name. They already said it in the Meadow square. The new matriarch shouted it, mine and two others, in front of everyone.",
                 "My name is Ceniza. That one you can know. The other, the real one, the whole Meadow knows now. For the Court, a shadow whose name has been spoken is a dead shadow."],
           opts: ["“Why did the matriarch do it?”", "“What happens to a named shadow?”", "Hide her in the Ford", "Take her before the king", "Leave and let her be"] },
      porque: { say: ["Because the king confessed the Wells pact on the Moonless Night. We shadows got our names back, and the borrowed quarter was over.",
                      "The matriarch got angry. She said that if the Court broke the deal, so would she. And she read out three names from a box Albor kept."] },
      pasa: { say: ["That anyone can call her. And the one called by her true name has to go. It isn't law, it's what we are.",
                    "Last night someone shouted my name under the window. Luckily he was drunk and got a letter wrong."] },
      vado: { say: ["Ceniza follows you to the Ford without speaking. At the door, she lowers her hood. Her face is very young and very tired.",
                    "Here nobody knows my real name. For now. Thank you, even if it doesn't last forever."] },
      rey: { say: ["In the largest tent, King Lóbrego receives you without his veil. It's the first time you've seen his face: an old man with sunken cheeks who no longer looks like a king.",
                   "Ceniza. I told you not to go out.",
                   "I confessed so my people could get their names back, Caretaker, and all I achieved was that three of them lost theirs for good. That's how fixes go. One pays and another collects."],
             opts: ["“What does the Court need?”", "“It was your fault.”"] },
      necesita: { say: ["A place where a name can't be shouted. And someone from above who sees us as something more than a debt.",
                        "If you call the peoples to the Heart, the Court will go. Veiled or unveiled. I have nothing left to hide."] },
      culpa: { say: ["It was. And yours too, and the matriarch's, and old Albor's, and everyone who drank from that light.",
                     "Ceniza stays with him. The king puts a hand on her shoulder, clumsily, like someone who never did it before."] },
      irte: { say: ["As you leave you hear someone, far off, shout a name you don't know. The curtain moves."] },
    } },
  });

  add("lake", {
    "e2-ciego": { who: { marejada: "Mother Marejada", orilla: "Orilla" }, nodes: {
      a: { say: ["The Mirror Lake no longer reflects. The water is clean and still, but when you lean over you see neither your face, nor the sky, nor anything. Only a smooth grey, like an eye with a cataract.",
                 "We came back because they told us the lake was cured. And it is. It has no sap. It has nothing. I've watched it for a week and it shows me neither tomorrow nor yesterday.",
                 "Beside her, Orilla reads her oilcloth notebook under her breath, turning old pages."],
           opts: ["“What happened to the lake?”", "Talk to Orilla", "Put your hand in the water", "“Mother, tell your people what you saw thirty years ago.”", "Leave them something to eat"] },
      paso: { say: ["The Root is asleep. The lake is the Root's eye: when it sees, the lake sees. Now its eyes are closed.",
                    "What nobody says is that a mother who sleeps like that doesn't wake to feed her children."] },
      orilla: { say: ["I'm looking in my mother's notebook to see whether this has happened before. Once. Long ago. The handwriting is very old, it isn't hers.",
                      "It says: “The lake did not reflect for three generations, until the Singer wept into it.” It doesn't say why she wept."] },
      mano: { say: ["The water is warm. When you pull your hand out, for a second a reflection that isn't yours stays in your palm: a woman with her mouth open, made of stone. Then it fades."] },
      contar: { say: ["They already know. Orilla told them. And since then half of them look at me as a liar and the other half as a coward.",
                      "But you're right about one thing. Whatever I don't tell, the lakeshore will tell when it dries.",
                      "That night, on the shore, Marejada speaks before all the Tides. She doesn't say much. She ends by asking forgiveness. Some leave. Most stay.",
                      "If one day we have to sing at the Heart, the Tides will go. Together, for the first time in thirty years."] },
      comer: { say: ["You leave them bread and fruit. Marejada accepts it without looking at you. “It isn't pride,” Orilla says. “It's that she finds it hard to accept things she didn't see coming.”"] },
    } },

    "e2-mudo": { who: { nasa: "Grandma Nasa" }, nodes: {
      a: { say: ["On the shore, among the beached boats, an old woman holds something wrapped in a fishing net. It glows a little. It's a Star the size of a fist, mouthless, still.",
                 "The water brought it this morning. From the Meadow, I'd say, that's where everything left over comes from. It makes no sound. It doesn't eat. It looks.",
                 "Unísona goes up to it on its own. The mouthless Star lifts its light a little, the way you lift your head."],
           opts: ["Let Unísona sing to it", "“How many like this one wash up?”", "Take it to the healer of the White Deep", "Leave it in the water"] },
      cuantas: { say: ["Three this week. The other two arrived already out. The children use them as stones to throw in the water. They don't skip.",
                       "In my day a Star was once in a lifetime, and there was a feast. Now they float on the shore like dead fish."] },
      unisona: { say: ["Unísona sings one long note and then falls silent, waiting. The Mute Star has no mouth to answer. But it glows in time, once, twice.",
                       "When Unísona stops, the Star keeps glowing. Brighter than before.",
                       "There you are. Now it has someone who listens to it. Take it with you. Give it a name."] },
      curandera: { say: ["You carry it in your pack as far as the road to the White Deep. When you take it out, it no longer glows.",
                         "Unísona doesn't sing the whole way back."] },
      agua: { say: ["You leave it in the water. It sinks slowly, glowing less and less. The lake, which reflects nothing, reflects that: a light going out."] },
    } },
  });

  add("caves", {
    "e2-noche": { who: { basalto: "First Pick Basalto", pirita: "Pirita, digger" }, nodes: {
      a: { say: ["It's the Night of the Echo. The families of the Hondura strike two stones at the entrance to the Hall, as the rite demands, and say their dead's names out loud. The cave always answered in their voice.",
                 "Tonight the cave doesn't answer. Strike, name, silence. Strike, name, silence.",
                 "Since they took the Guardian's verse, nobody answers. My father died last year and I haven't heard him once."],
           opts: ["Strike two stones yourself", "Talk to the First Pick", "Sing what Grava taught you", "Leave in silence"] },
      golpear: { say: ["You strike two stones. It sounds dry, with no echo. A Hondura child copies you, harder, as if it were a matter of strength."] },
      basalto: { say: ["Don't look at me like that. I know what you're thinking. I sold the maps. You took the verse. Between the two of us we left the Hondura without its dead.",
                       "The stone says it, and stone is the only thing that doesn't lie: those digging with my maps under the Meadow have already crossed the Line. I feel it in my hands, like a tremor."],
                 opts: ["“Come to the Heart when I call. We have to fix this together.”", "Go back to the entrance"] },
      juntos: { say: ["The Hondura never sings. We strike stones. If you call me, I'll come with two stones and the people behind me.",
                      "And I'll tell you something I've told no one. The Guardian repeated a verse that belonged to no people. I half remember it: “as long as no one drinks...”. I don't know the rest."] },
      grava: { say: ["You sing the first verses Grava sang with you. At first, nothing. Then, from very deep down, faintly, the cave repeats a word: “...drinks...”.",
                     "The families stand still. Pirita weeps without a sound.",
                     "It's her. She's still in there, somewhere. If one day the Hondura has to go to the Heart, we'll take her with us."] },
      irte: { say: ["Behind you the strikes go on. Strike, name, silence. All night."] },
    } },

    "e2-pozo": { who: { brida: "Brida, forewoman" }, nodes: {
      a: { say: ["Following a new tunnel, on no old Hondura map, you reach a huge chamber beneath the Meadow. In the centre a long glass tube, very long, runs down into a bottomless hole. It's a Blind Well.",
                 "The tube pulses. Light rises inside it, white and thick, towards the Meadow. All around, the rock sweats black sap.",
                 "You shouldn't be here. Nobody should be here. Not even me."],
           opts: ["“Brida, this is killing the Root.”", "Look into the hole", "Seal the well with the loose rock", "Take a piece of the tube to show in the square", "Leave it open: it's the Quarter's light"] },
      matando: { say: ["I know. I've known since last week, when my partner's hands turned black. Half the diggers know.",
                       "But if you close this, tomorrow the Dim Quarter is dark again. And the matriarch falls. And they take away the name she gave me."] },
      mirar: { say: ["You lean over. Far below, further down than anything should exist, something huge and dark stirs in its sleep. Every time the tube swallows, it flinches, like someone feeling cold.",
                     "Unísona covers its face with its paws. Its whole body is shaking."] },
      tapar: { say: ["You push loose rock against the mouth of the well. At first Brida just watches. Then she helps. It takes all night. The tube cracks, the light goes out, the pulse goes on.",
                     "Up there, a street in the Quarter just went dark. Tomorrow they'll ask me who did it.",
                     "I'll say it collapsed on its own. For once in my life I'll lie to her."] },
      denunciar: { say: ["You tear off a piece of tube, still hot, with black sap stuck to it. Brida doesn't stop you.",
                         "Show it. Let them see. But don't say you found it here, or tomorrow they hang the diggers and the matriarch stays as she is.",
                         "The next day, in the Meadow square, people look at the glass shard and murmur. Destello comes out on the balcony and says it's Shadow sabotage. Half the square believes her."] },
      abierto: { say: ["You turn away. Behind you the tube keeps pulsing, swallowing, sending up light for a thousand lanterns.",
                       "Thank you. I won't forget it. Neither will the Quarter.",
                       "Unísona doesn't follow you at once. It stays staring at the hole until you call it three times."] },
    } },
  });

  add("deep", {
    "e2-setas": { who: { esporina: "Esporina", yesca: "Yesca, grower" }, nodes: {
      a: { say: ["The mushroom fields of the White Deep are grey. The caps fall off by themselves, crumbled to dust. Since the sap cleared, the mushrooms that grew on it are dying.",
                 "They're the remedy ones. The ones that cured sap fever. Without them, the sick who'd recovered are falling ill again.",
                 "At the back, a woman with an enormous hat digs a hole in the ice with a shovel. She's already in it up to her waist."],
           opts: ["Talk to the woman with the shovel", "“How many sick have fallen ill again?”", "Help her dig", "“If you dig there, you'll wake it. Stop.”", "“Let's look for another remedy, without sap.”"] },
      cuantos: { say: ["Thirty in the Deep. In the Meadow I don't know, they don't count the Quarter folk up there.",
                       "The healer says the Heart's cure cured everyone except those who were already cured. I don't know if it's a joke."] },
      esporina: { say: ["Don't look at me like that, I'm not mad. Mushrooms grow where the sap is thick. The thickest left is down here, under the ice, where nobody put it fully to sleep.",
                        "You defended my remedies, remember? You got me permission to heal by day. Well, this is the price: to heal, I need the Root to stay a little sick."] },
      cavar: { say: ["You dig with her until the ice turns dark. Underneath, a vein of black sap, thick as honey. Esporina weeps with relief.",
                     "With this I can cure thirty. With a little more, the whole Quarter.",
                     "Beneath your feet, very deep, something turns over in its sleep."] },
      parar: { say: ["And what do I tell the thirty? To put up with it because the Caretaker is afraid of a root?",
                     "But she drops the shovel. She sits on the edge of the hole, feet dangling.",
                     "Fine. I'll stop. But when the first one dies, you'll be the one to tell their mother."] },
      otro: { say: ["A remedy without sap? I've been looking for one for twenty years.",
                    "Although... Grandpa Liquen says the Root breathes. If it breathes, it dreams. And if it dreams, maybe the dreamers of the Watch could... no, it's nonsense.",
                    "It isn't nonsense. She writes it inside her hat, in charcoal."] },
    } },

    "e2-oyen": { who: { nevisca: "Nevisca, dreamer of the Watch", albina: "Regent Albina" }, nodes: {
      a: { say: ["In the Watch hall, where the dreamers keep vigil over the Frozen Tomb, there are more people than ever. They sit in a circle with their eyes closed, repeating something under their breath, all at once.",
                 "The king has spoken again. For the first time in centuries, we truly hear him. Not like before, when they told us what to dream.",
                 "He says he's thirsty. That he wants to wake. We call ourselves Those Who Hear."],
           opts: ["Sit in the circle and listen", "“Who used to tell you what to dream?”", "Go and see the regent", "Join Those Who Hear"] },
      antes: { say: ["The regency. Everyone knows and nobody says: the Regent wrote the king's dreams and gave them to us to learn. I dreamed a dream she wrote for two years myself.",
                     "But nobody wrote this one. This one comes from below."] },
      escuchar: { say: ["You close your eyes. After a while, in the dark, you feel something enormous turning over, with a dry mouth, that doesn't remember why it promised to sleep.",
                        "You open your eyes with a dry throat. Nevisca smiles at you. Her lips are cracked, like everyone's in the circle."] },
      regente: { say: ["Those Who Hear. What a pretty name for a bunch of dreamers who stopped obeying.",
                       "I invented the king's dreams for years. These aren't mine. And that's what frightens me, Caretaker: that for the first time what they dream is true, and the truth asks for something terrible."],
                 opts: ["“Tell them you invented the old dreams.”", "“The circle has to be broken up.”"] },
      verdad: { say: ["And be left without a regency? Without anything holding together three houses that hate each other?",
                      "But she goes down to the hall. Before the circle, her voice breaking, she tells how she wrote the dreams. Many weep. Some leave. Nevisca stays.",
                      "There. Now I'm nothing. If the Heart calls the peoples, the White Deep will go, but not behind me: behind all of you, who asked for it."] },
      disolver: { say: ["At last someone with common sense. Guards.",
                        "The Tomb guard takes the dreamers out one by one. Nevisca, passing you, looks at you with pity.",
                        "You can take us out of the hall. You can't take the dream out of us."] },
      unirte: { say: ["They give you a grey ribbon for your wrist. From that night on, every time you sleep, you hear a little more of the thirst of something very large."] },
    } },
  });

  add("heart", {
    "e2-estatuas": { who: { cincel: "Cincel, sculptor" }, nodes: {
      a: { say: ["Around the Stump, the ground has sunk with the Calm. Where there used to be one moss-covered statue, now four show through, buried at different heights, like steps.",
                 "Forty years I've cleaned the Singer's statue and I never knew she had sisters. Look at the mouths. All four, open in the middle of a note."],
           opts: ["Look at the deepest statue", "Look at the middle one", "Clean the base of the Singer's statue"] },
      honda: { say: ["The deepest has its face erased. Not by time: by blows. Someone went to a lot of trouble so nobody would know who it was.",
                     "That's chisel work. A very old one. A sculptor doesn't erase a face like that. Someone ashamed does."] },
      medio: { say: ["Two of the middle statues are two figures holding hands, one with frost in its hair and one in a mushroom hat. The other has forge slag stuck to its base, as if it turned to stone while working.",
                     "The Nameless Smith. The Ember folk pray to him. They think he's theirs and nobody else's. Look where he is: below the Singer. Before her."] },
      base: { say: ["With a brush and water you clear the moss from the base of the Singer's statue. Underneath are letters, worn but legible. It isn't a verse of any people. It's a single sentence:",
                    "“I will sleep as long as no one drinks beneath my dreams.”",
                    "That isn't in the Song. Nobody sings that.",
                    "Unísona reads the letters with its paw, one by one, and its light goes out for an instant, as when you remember a promise someone else broke."] },
    } },

    "e2-coros": { who: { brezo: "Brezo, keeper of the Stump" }, nodes: {
      a: { say: ["At the edge of the Stump four choirs are camped, each with its banners. The Lantern Houses, the Guild, the White Deep and a group from the Heights. Each rehearses its verse, louder than the one beside it.",
                 "They arrived this week. Each says its verse is the heart of the Song and that, if they sing it alone, the Root will fall fully asleep. They've gone three days without letting each other sleep."],
           opts: ["“What happens if all four sing at once?”", "Ask them to sing together", "Tell them about the statue's base", "Let them rehearse"] },
      vez: { say: ["They did it yesterday, by accident. The ground shook and sap came out of a new crack. Since then they take turns, and insult each other between turns."] },
      juntos: { say: ["You talk with all four. They all listen respectfully: you're the one who calmed the Root. None of them agrees. Each wants to sing first.",
                      "The First Singer told each of them their verse was the heart. It was so they'd look after it. Now it's so they don't listen to each other."] },
      noveno: { say: ["You read them the sentence from the base. There's a long silence, the first in three days.",
                      "“That's a condition,” says a man from the Guild. “It isn't a verse. You don't sing a condition, you keep it.” “Then let the others keep it,” a woman from the Houses replies.",
                      "At least now they know what was broken. Knowing isn't fixing, but it's something."] },
      dejar: { say: ["You walk away among the rehearsals. Four verses, four voices, no lullaby."] },
    } },

    "e2-final": { who: { tila: "Tila", nim: "Nim" }, nodes: {
      a: { say: ["The Wakeful Root won't sleep. You beat it, it fell, it rose again, and it's still down there, eyes open in the dark. Every lullaby sung to it angers it more. The Stump shakes day and night.",
                 "In the middle, Tila and Nim are waiting for you. Unísona stands between them, half dimmed, looking at the base of the statue.",
                 "We have to decide something. We can't wait for it to calm down on its own anymore.",
                 "There are three ways. None of them is good. You choose, it listens to you."],
           opts: ["“What happens if I sing, louder than anyone?”", "“And if we close every well?”", "“And if we sing with only those who are here?”", "Sing louder than anyone and stay in the Heart", "Gather the nine peoples to sing the condition as a promise", "Sing with the peoples who came"] },
      q1: { say: ["The Root sleeps another generation. There'll be a feast in the Ford and they'll make you a beautiful statue. The fifth.",
                  "And you stay here, singing, until your skin turns to stone. Like them. And the wells stay open, and in fifty years, another Caretaker."] },
      q2: { say: ["We have to sing the sentence from the base as a promise, not as a lullaby. With the nine peoples in front, and Unísona as witness.",
                  "The Root doesn't sleep: it stays awake, drinks what's its own and heals for real, very slowly. And we close every well. Every one. The Meadow goes dark.",
                  "And the Houses that lose their last light lose their name. That's their law. You know that, Tila.",
                  "I know."] },
      q3: { say: ["We sing with the peoples you brought. The Root half sleeps, with one eye open.",
                  "Where its people came, the sap settles. Where nobody came, it keeps coming out. A divided Glade: healthy zones and black zones."] },
      quinta: { say: ["You climb the Stump and sing. The eight verses, and Tila's lullaby and Nim's, and the sentence from the base as if it were one more lullaby. You sing louder than all four choirs together.",
                      "The Root falls asleep. The shaking stops. In the Ford, bells begin to ring.",
                      "You can't come down. You don't want to. Your feet are heavy. Tila holds your hand for a long while, until your hand is no longer warm.",
                      "We'll make you a beautiful statue. I promise. And we'll sing to you, so you'll never lack company."] },
      linea: { say: ["The nine arrive. The Houses with Alvar in front, the Fire with its hammer, the Wood in silence, the Heights selling nothing, the Court unveiled, the Tides together, the Hondura with two stones, the White Deep without its regent, and the Dim Quarter, which belongs nowhere and to everyone.",
                     "They don't sing a lullaby. They say the sentence from the base, all at once, looking down: “No one will drink beneath your dreams.” Unísona shines among them all, brighter than ever. It is the witness.",
                     "The Root doesn't fall asleep. It stays awake. It drinks slowly from what's its own. And it stops shaking.",
                     "Now the wells have to be closed. All of them. Starting with my House's, which no longer exists.",
                     "That night, for the first time in thirty years, the Meadow is dark. The stars come out."] },
      ligero: { say: ["The peoples you brought sing, each its verse, one after another, without fighting. You sing the ending. Unísona sings with you.",
                      "The Root grows drowsy. Not completely. The shaking drops to a murmur, like someone sleeping badly.",
                      "Look at the map. Where a people came, the ground is still. Where nobody came, the sap keeps coming out.",
                      "A Glade split in two. At least this time we know where the crack is."] },
    } },
  });
  /* ==================== Delivery 2: the Day (Aurora Meadow, Warm Crater, Deep Forest) ==================== */

  add("aurora", {
    "e2-aurelia": { who: { aurelia: "Aurelia Albor", alvar: "Alvar" }, nodes: {
      a: { say: ["In the back yard of the Dawn Tower, among flowerpots, an older lady in a good dress with soil-dirty hands is talking to a geranium.",
                 "You, further left. You don't get the sun there. How many times do I have to tell you?",
                 "She sees you. She isn't surprised. She wipes her hands on the dress, which once was worth as much as a house in the Quarter.",
                 "The Caretaker. Come in. I have no guards left to stop you. I'm Aurelia Albor, in case you don't remember. These days I rule the flowerpots."],
           opts: ["“Why did they put you aside?”", "“What do you think of the new matriarch?”", "Ask about Alvar", "“You know where Albor dug. Do you have it written down?”", "Help her with the flowerpots"] },
      porque: { say: ["Because of the tubes. Someone had to pay, and I was the one who signed. It's fair. I'm not complaining.",
                      "Well, I complain a little. To the flowerpots. They don't vote on the Council.",
                      "She moves the geranium to the left. Then to the right again."] },
      destello: { say: ["That she's clever. Cleverer than I was at her age. And that she's right about almost everything, which is the most dangerous thing a person can be.",
                        "When I opened the first well, I was right too. The Meadow was cold. Do you know what it is to be told you're right every day for thirty years? You stop caring to look at the ground."] },
      alvar: { say: ["My grandson goes around in muddy boots with friends from the Quarter. It makes me glad. I mean it.",
                     "What I don't want is for him to carry what's mine. In the Meadow, surnames weigh more than people. They'll charge him for what I did, just as they charged me for what my mother did.",
                     "If he ever has to choose between his name and what's fair, he shouldn't think twice. Tell him that from me. He doesn't listen to me."] },
      libro: { say: ["Of course I have it. Albor wrote everything down. Even what it shouldn't have.",
                     "From among the pots she takes a tin box. Inside is a notebook with red covers, worn at the corners.",
                     "Every well we opened is here, how much it gave and when it started giving black. Lucerna believes she digs where it bothers no one. I believed it too. Look at the page for year thirty-two.",
                     "On that page there's a drawing of the ground under the Meadow. Albor's wells are marked with crosses. Below them all, in a shaky hand, someone wrote: “Deeper there is nothing else. There is the same thing, closer.”"],
               opts: ["“Give it to me. I'll take it to the matriarch.”", "“It should be read in the square, in front of everyone.”", "“Burn it. It's done enough harm.”", "Hand back the box and say nothing"] },
      llevar: { say: ["Take it to her. But promise me one thing: if she asks where you got it, tell her you found it. Alvar's name stays out of this.",
                      "She gives it to you with both hands, the way you hand over something heavy. Before letting go, she squeezes it for a second.",
                      "Thirty years. And it fits in a pocket."] },
      plaza: { say: ["In the square? They'd throw stones at me. And they'd be right, but stones don't plug wells.",
                     "Do what you like with it. But if you read it in the square, people won't hear “the Root”. They'll hear “Albor”. And Lucerna will say it's the old House's revenge. And they'll believe her.",
                     "She gives it to you anyway. She's right, and she knows it, and that seems to tire her more than anything."] },
      quemar: { say: ["Aurelia looks at you for a long while. Then she strikes a match, very slowly, and brings it to the corner of the notebook.",
                      "Before it catches, she blows it out.",
                      "No. Burning papers is what my mother did. That's why I knew nothing when my turn came.",
                      "I'll keep it. If someone needs it one day, let them come and get it. They'll know where I am: giving orders to a geranium."] },
      macetas: { say: ["You repot three geraniums. She corrects every one. At the end, without looking at you, she says you did well.",
                       "In the soil of the pots, when you push your fingers in, there are very fine black threads. Aurelia sees them. She heaps more soil on top, carefully, like someone tucking in a child."] },
    } },

    "e2-pabilo": { who: { pabilo: "Pabilo", guarda: "Lantern Guard" }, nodes: {
      a: { say: ["The Meadow's new lanterns light themselves at dusk. Nobody climbs ladders, nobody carries cans. A glass tube runs down from each one into the ground.",
                 "At the foot of one, sitting on his folding ladder, the old lamplighter watches it light up without him. His empty cans are at his feet and the pole rests on his shoulder, like the rifle of an army that no longer exists.",
                 "Forty years climbing. Now they climb by themselves. They pay me half to watch that they don't go out. They never go out."],
           opts: ["“Isn't it better like this? You don't have to climb anymore.”", "Look at the lantern up close", "“You told me about the cold light, last year.”", "“Light an oil one. Just one, in the Quarter.”", "Buy his old pole", "Leave him watching"] },
      mejor: { say: ["Better for the knees, yes. The knees have no opinion on the rest.",
                     "An oil lantern flickers. It breathes. If the wind changes, it ducks. These don't duck for anything. A light that doesn't duck for anything isn't alive, lad. Sorry: Caretaker."] },
      mirar: { say: ["The flame doesn't move. Not even a little. It's like a painting of a flame.",
                     "At the foot of the tube, where it goes into the earth, the grass is yellow in a perfect circle. As if someone had sucked the green out of it with a straw."] },
      fria: { say: ["You remember. Nobody remembers what a lamplighter says.",
                    "This one's colder still. Put your hand here. See? It lights and doesn't warm. It takes the light out of something and gives nothing back."] },
      aceite: { say: ["An oil one? The matriarch's guards are taking them down. They say they're ugly.",
                      "That gentleman knows he can't light anything without a permit.",
                      "Pabilo looks at you. You look at the guard. The guard looks away, because he's from the Quarter and his grandmother had an oil lantern in her window."],
                opts: ["Light it anyway, on Penumbra's corner", "Talk the guard round", "Leave it for another day"] },
      prender: { say: ["Pabilo climbs his ladder, slowly, knees creaking. He fills the can. He lights the wick. The flame ducks in the wind and rises again.",
                       "There it is. That one breathes.",
                       "After a while, the neighbour across the street brings a chair out to her door and sits under the oil lantern, even though the new one gives more light. Then another. By midnight there are six chairs."] },
      guarda: { say: ["Look, Caretaker, I don't want trouble. If the captain asks tomorrow, the lantern was already like that.",
                      "Pabilo lights his lantern. The guard turns his back, standing very straight, looking in exactly the opposite direction."] },
      pertiga: { say: ["My pole? What do you want it for? There's nothing to light.",
                       "Well. Take it. Better it's with someone who still walks at night.",
                       "It's heavier than it looks. Near the tip there are forty notches carved: one for each year."] },
      irte: { say: ["As you walk away, Pabilo is still there, sitting, watching a flame that doesn't move. Neither does he."] },
    } },

    "e2-brizna": { who: { brizna: "Brizna", recolector: "Tower collector" }, nodes: {
      a: { say: ["In the usual alley, the girl who drew with chalk is crouching beside a glass jar. She's grown. Inside the jar are twelve tiny Stars, dark, grey as river stones.",
                 "Don't touch them, they break. I pick them up at the foot of the choir stage. Nobody wants them. They sweep them out with the rubbish.",
                 "On the wall, in chalk, she has drawn twelve faces. Each one has a name underneath."],
           opts: ["“Why did you give them names?”", "“What are they, to you?”", "Show her the Star you saved from the choir", "“Let's bury them properly.”", "“Let Unísona see them.”", "Ask who else looks for them"] },
      nombres: { say: ["Because they were born from a song and nobody was expecting them. Like me. The neighbour named me, because my mum was very tired.",
                       "This is Mota. This is Pica. This one has no name yet because it came yesterday and was already dark when I found it."] },
      que: { say: ["Promises. The girl on the roof said so. That when you sing someone else's lullaby without meaning it, out comes a promise with no owner, and it goes dark because nobody keeps it.",
                   "I think they're cold. That's why I keep them together."] },
      tuya: { say: ["You take out the Star wrapped in your scarf. It still shines, a little, like a candle seen from far away.",
                    "When you bring it close to the jar, the twelve grey Stars light up for an instant. All at once. Then they go dark again.",
                    "Did you see! Did you see! They remembered. They're alive inside, just very tired."] },
      enterrar: { say: ["You bury them together under the alley's last oil lantern, in a biscuit tin. Brizna says a name for each one. Your creatures dig with their paws.",
                        "That way, if someone sings nicely up here, they'll hear it.",
                        "That night, on the turned earth, there's a very faint glow. By dawn it's gone."] },
      unisona: { say: ["Unísona goes up to the jar. It looks at them for a long time. Then it sings a single note, the lowest you've ever heard from it.",
                       "Nothing happens. The Stars stay grey. But Unísona doesn't move from there until night falls, and Brizna sits down beside it.",
                       "It's sad. Creatures get sad too, did you know? The ones that sing, more."] },
      busca: { say: ["A man from the Tower. He comes on Thursdays with a box lined with velvet. He pays a coin for each one.",
                     "As if she had called him, a man in white gloves with a box appears at the end of the alley.",
                     "Ah, the stone girl. The matriarch wants to study them. If the Stars come out of the choir, she wants to know what they're made of. To make better choirs."],
             opts: ["Sell them to him yourself, for double", "Stand between the man and the jar", "“What does the matriarch do with them?”"] },
      estudio: { say: ["They open them. Inside there's something like a written note, they say. The same note in all of them, one nobody knows how to sing.",
                       "I don't know about such things. I get paid by the box."] },
      vender: { say: ["The man pays double without blinking. Brizna says nothing. She puts her hands in her pockets and looks at the wall with the twelve faces.",
                      "That night, when you pass by again, the chalk faces have been rubbed out. All but one, the one with no name."] },
      defender: { say: ["As you like. They're stones. There are more at the stage.",
                        "He leaves. But at the corner he signals to a guard, and the guard follows you with his eyes until you leave the Quarter."] },
    } },

    "e2-penumbra": { who: { penumbra: "Penumbra", cirio: "Cirio, notice-board warden" }, nodes: {
      a: { say: ["In the Shadow seamstress's workshop there's more work than ever. On the table, hundreds of grey cloth ribbons. On each one, embroidered in white thread, a name and a destination.",
                 "The Law of Return asks every family to wear its ribbon sewn on their coat. Name, House that pays, and the place they go back to. That way the Threshold guards know whom to let through and whom not.",
                 "They pay me well. I embroider forty a day. I used to embroider linings so the dust wouldn't get into people's lungs. Now I embroider this."],
           opts: ["Read some of the ribbons", "“Do you have to go back too?”", "“What if some ribbons said “Ford” instead of “Underside”?”", "Just help her embroider", "Take the ribbons to the board to be sealed"] },
      leer: { say: ["“Ceniza family. House Albor. Hollow, the house by the bridge.” “Rocío family. House Destello. Lake, south shore.” “Nameless family. House Alba. Caves, gallery nine.”",
                    "That last one has no name because they wouldn't take one. They put “nameless” and that was that. It's what they did in the Wells. Some things don't change, they just get embroidered prettier."] },
      ella: { say: ["My ribbon says “Hollow, Loom Street”. That street doesn't exist anymore. The mist ate it twenty years ago. But the paper says it's cured, so it must be there.",
                    "I embroidered it myself. With my best thread. If they're going to throw me out, at least let it look well made."] },
      cambiar: { say: ["Penumbra puts down her needle. She looks at you over her glasses.",
                       "Do you know what happens to me if they find out? They take my permit. Mine, and I have a ribbon. And then those with the changed ribbons.",
                       "But the Threshold guards can't read well. None of them. They look at the seal and the shape of the letters. If the word is short and round…",
                       "She picks up a ribbon. Instead of “Underside” she embroiders, very slowly, “Ford”. Stitched in the Glade's old letters, the two words look alike if you don't look too hard."],
                 opts: ["“Do it with as many as you can.”", "“Only the families with small children.”", "“Better not. It's too dangerous for you.”"] },
      todas: { say: ["You embroider until dawn. A hundred and twelve ribbons say “Ford”. Your fingers bleed a little. Hers don't: she has forty years of calluses.",
                     "Now the Ford will have to make room for them, Caretaker. A hundred and twelve cold people. Did you think of that?",
                     "You hadn't, not entirely. But it's embroidered now."] },
      ninos: { say: ["Thirty ribbons. Those of the families with children born up here, like Umbría's.",
                     "It's an ugly choice. Choosing who gets to. But it's better than choosing nobody.",
                     "While you embroider, she sings very softly. It isn't the lullaby. It's a workshop song, to keep the needle's rhythm."] },
      nocambiar: { say: ["Thank you for thinking of me. Almost nobody does.",
                         "She goes back to her needle. “Underside”. “Underside”. “Underside”. Perfect stitching, every one."] },
      ayudar: { say: ["You embroider all afternoon. It isn't hard. What's hard is reading each name before you stitch it.",
                      "You have a good hand. Pity it's for this."] },
      sellar: { say: ["You carry the basket of ribbons to the Ford's board. Cirio seals them one by one with red wax.",
                      "Hardly anyone helps. People walk past and glare, as if I'd written the law.",
                      "When you get back to the workshop with the empty basket, Penumbra doesn't look up from her needle."] },
    } },

    "e2-romero": { who: { romero: "Romero, gardener", alvar: "Alvar" }, nodes: {
      a: { say: ["At dawn, in the Tower gardens, the gardener is pulling up flowers. Heaps of them. He stuffs them into black sacks and ties them with a double knot.",
                 "Don't look. Orders. Every night they come up like this and every morning I pull them before the Meadow wakes.",
                 "One falls out of a sack. It's a perfect rose, red on the outside. The centre, where the pistils should be, is black and glossy like oil."],
           opts: ["“Since when have they come up like this?”", "“Who gives the order?”", "“The grey flowers from last year… do you remember?”", "“Give me a sack. I'll take it to the Council.”", "Plant one in the Ford, to see what happens", "Help him pull them up"] },
      cuando: { say: ["Since the Night of Lanterns. The night of all the lanterns. The next day the first ones came up. Now they're half the garden.",
                      "The strange thing is they grow better than the others. Bigger, redder. If it weren't for the centre, they'd be the most beautiful flowers I've ever grown."] },
      quien: { say: ["The matriarch. She told me herself, very politely. That people scare easily, that it's a passing blight, that her engineers are looking into it.",
                     "She raised my wages. Nobody had ever raised my wages. So I pull."] },
      grises: { say: ["The grey ones were sad. They died slowly. These don't die. These eat.",
                      "He opens his hand. On the palm, where he touched the stems, there's a dark stain that won't wash off."] },
      consejo: { say: ["To the Council? They're meeting today in the great hall. They'll kick you out.",
                       "But here. If they throw you out, let them throw you out with the sack."],
                 opts: ["Walk in through the front door and empty the sack on the table", "Give it to Alvar, who still gets in through the Houses' door"] },
      mesa: { say: ["The guards are slow to react. You empty the sack onto the Council table. Forty red roses with black hearts fall onto the papers of the Law of Return.",
                    "A long silence. Then someone from an old House starts shouting that it's a Shadow provocation. Someone else shouts that it's Albor's fault. Nobody looks at the flowers.",
                    "Only one person comes over to touch them: Lucerna Destello. She looks at them for a long time. Then she orders you taken out."] },
      alvar: { say: ["Me, take them? If I take them, they'll say it's my grandmother's doing.",
                     "Well. Let them. My grandmother once told me that if I had to choose between my name and what's fair, I shouldn't think twice.",
                     "He slings the sack over his shoulder and walks in through the Houses' door. The guards greet him. From outside you hear an enormous silence fall."] },
      vado: { say: ["You plant one rose in a pot, by the door of your house in the Ford. Three days later the pot is cracked. The roots came out of the bottom and went into the earth, seeking towards the Heart.",
                    "Unísona won't go near the pot. Neither will your creatures. On the fifth day you burn it."] },
      arrancar: { say: ["You pull until midday. The sacks pile up against the garden wall. In the afternoon a cart comes and takes them. Nobody says where.",
                        "Thank you. It's easier with someone. You feel less of an accomplice."] },
    } },

    "e2-cira": { who: { cira: "Old Cira", nim: "Nim" }, nodes: {
      a: { say: ["The old woman from the bench isn't on the bench anymore. She's in her bed, in a small room in the Quarter, with the window open towards the choir stage. Nim is sitting on the floor beside her, peeling an orange.",
                 "Old Cira won't let me close the window. She says she wants to hear them wreck her songs.",
                 "They don't wreck them, son. They sing them without wanting to. It's worse."],
           opts: ["Sit with them", "“You knew the two lullabies were the same.”", "“Is there a verse nobody sings anymore?”", "Close the window"] },
      sentar: { say: ["Nim gives you a piece of orange. Old Cira breathes slowly. Outside, the choir starts again.",
                      "My grandmother sang for rain. My mother, so my brothers would sleep. I sang to bury my husband. These children sing to get paid. It isn't wrong. But the song notices."] },
      iguales: { say: ["Not the same. Sisters. Like two girls so alike that people mix them up, and they let themselves be mixed up because it suits them.",
                       "But something's missing in both. It always was. My grandmother said the whole lullaby had one more verse, and that it was lost the day they divided the Glade."] },
      verso: { say: ["There is one. My grandmother sang it only at the end, when she thought I was already asleep. It wasn't for sleeping. It was something else.",
                     "I don't remember the tune. Only the words, and not all of them. It went something like: “And if you wake, you won't wake alone; what we have taken, we will give back.”",
                     "That's not a lullaby. It's a promise.",
                     "That's why nobody sings it, son. Lullabies are easy. Promises have to be kept."],
             opts: ["Ask her to repeat it so you can write it down", "“There are words on the base of a statue in the Heart.”", "Let her rest"] },
      escribir: { say: ["She repeats it three times. Each time she changes a word, as if searching for the right one among many that look alike.",
                        "You write it on the back of your map. Nim reads it over your shoulder, moving his lips.",
                        "Now you know it too. It doesn't die with me anymore. What a relief, you know? It's a weight, a verse only one person knows."] },
      estatuas: { say: ["You tell her the words on the Singer's base: “I will sleep as long as no one drinks beneath my dreams.”",
                        "That's what she asks. My grandmother's verse is what we answered her. A lullaby with a question and an answer, child. It split in two, and each people kept the half that commits it to nothing.",
                        "She squeezes your hand with a strength you didn't expect. Then she lets go and closes her eyes."] },
      descansa: { say: ["Old Cira falls asleep with her mouth a little open. Nim finishes the orange. Outside, the choir goes flat on the same note as always.",
                        "I'll come again tomorrow. If you like, you come too. She likes having people near, even if she says she doesn't."] },
      ventana: { say: ["Open it.",
                       "You open it again. She smiles without opening her eyes.",
                       "A badly sung song is still a song. One day one of those children will sing it like they mean it, and I want to be listening."] },
    } },

    "e2-destello": { who: { destello: "Lucerna Destello" }, nodes: {
      a: { say: ["You're summoned to the Tower at night. Not to the hall, but to a small room on the top floor, with a table covered in papers and a window looking over the Dim Quarter.",
                 "From up here, the Quarter isn't dark. Every window has light. In some you can see children reading.",
                 "Sit down. I won't offer you wine, because I have none. I have Quarter tea, the usual.",
                 "I know what you've been doing. I'm not angry. I want to know what you want, because I want things too, and maybe we want the same ones."],
           opts: ["“Close the Blind Wells.”", "Put Albor's notebook on the table", "“What do you want?”", "Look out of the window without answering"] },
      ella: { say: ["That no child in the Quarter ever again reads by a tallow candle that ruins their eyes. That my mother doesn't die coughing in a windowless room, like Nim's did. That nobody from up here ever tells us again where we may live.",
                    "And I know where the light comes from, Caretaker. I'm not a fool. But Albor drew light for forty years for seven Houses. I've drawn it for one year for everyone. If the Root has to collect on something, let it collect on theirs first."] },
      ventana: { say: ["In the window across the way, a girl with an open book has fallen asleep on the pages. The light is on her face. She doesn't wake.",
                       "That's Candela. A year ago she couldn't read. Look at what you're asking me to switch off for her."] },
      cerrar: { say: ["All of them? Tonight? Then tomorrow the Quarter is dark again, and the old Houses rule again, because they're the only ones with oil stored away.",
                      "No. But I'll offer you something: a seat on the Council. A Caretaker with a voice. If you prove to me a well does harm, that well gets closed. One by one. With proof, not with fear."],
              opts: ["Accept the seat", "“I won't sit counting wells while the Root wakes.”"] },
      libro: { say: ["Destello opens the red notebook. She reads the page for year thirty-two. She reads it twice. The third time, with her finger.",
                     "“Deeper there is nothing else. There is the same thing, closer.”",
                     "She is silent for a long time. Outside, in the Quarter, a window goes dark. It's the sleeping girl's: someone turned off her light so she can rest.",
                     "My engineers told me the opposite. I paid them to tell me the opposite, didn't I? I didn't think of it that way, but it's what I did."],
             opts: ["“Close one a month. Start with the deepest.”", "“Close them all and tell the Quarter the truth.”", "“Keep the notebook. You'll know what to do.”"] },
      silla: { say: ["Good. Tuesdays, at teatime. Bring proof. And bring patience: the old Houses talk a lot.",
                     "She gives you a copper badge with a lamp engraved on it. It sits heavy on your chest."] },
      negar: { say: ["Then we're polite enemies. That's fine. I prefer them to friends who lie.",
                     "She walks you to the door herself. Before closing it, she says: “If you find another way to make light, I'm here. I mean it.”"] },
      cede: { say: ["One a month. The deepest first. The Houses will tell me I'm giving in to the Ford, and the Quarter will say I'm betraying it.",
                    "That's fine. That's what they elected me for: so someone from the Quarter makes the ugly decisions, instead of them being made for us.",
                    "She keeps the notebook. That night, in the Quarter, one window in ten takes a little longer to light."] },
      verdad: { say: ["All of them? And tell the Quarter that the light that cost them so much is poison? That the woman they chose was wrong?",
                      "They'll throw me off the Tower. And they'll put someone from Albor in, who'll open the wells again, but only for seven Houses.",
                      "She closes the notebook. She puts it in a drawer with a key.",
                      "Give me time. Not much. But don't ask me to cut off my own head to prove you're right."] },
      deja: { say: ["Destello lays her hand on the notebook, as on something still warm.",
                    "That's the cruellest thing anyone has done to me in a year. Giving me the truth and leaving me alone with it.",
                    "Thank you. I think."] },
    } },
  });

  add("crater", {
    "e2-termas": { who: { ascua: "Old Ascua", junco: "Junco, cooler" }, nodes: {
      a: { say: ["The Crater baths give off so much steam you can't see faces. There are people laughing in the water and people cooking eggs at the edge, in a net.",
                 "Lovely, eh! Forty years asking for the water to come back hot, and now it boils. You can't get more than your feet in.",
                 "She says it laughing. But her feet are out of the water, red, and she has a wet towel on the back of her neck."],
           opts: ["Put your hand in the water", "“Since when does it boil like this?”", "Ask Junco for dam water to cool it", "Measure the heat with a reed, as the old folk did", "Bathe your creatures at the edge"] },
      mano: { say: ["It hurts. Not like hot water: like touching someone with a fever who won't let go of you.",
                    "At the bottom, between the stones, there are bubbles that aren't air. They rise slowly and burst without a sound, with a sweet smell."] },
      cuando: { say: ["Since the Guild started making the long tubes. First it rose a little. Then more. Now, in the middle, it cooks an egg in the time it takes to say a prayer.",
                      "My grandmother said the earth had a fever when something was taken from it that it didn't want to give. My grandmother said a lot of things. Some were true."] },
      presa: { say: ["Dam water? We opened it last year, thanks to you. It comes down cool now.",
                     "Junco opens a trench with her shovel. Cold water rushes into the baths with a hiss like an iron. A cloud of steam covers everything.",
                     "When it clears, the water is warm again, the good kind. People clap. Ascua puts her legs in up to the knees and sighs.",
                     "This lasts a week, Caretaker. The dam cools the water. Whatever heats it is still down there."] },
      cana: { say: ["Ascua hands you a long hollow reed, with charcoal marks every hand's breadth. You sink it into the middle of the bath.",
                    "The old marks, from her grandmother's day, reached the third. Today's water scorches the reed up to the seventh. Inside, the reed comes out stained black.",
                    "Oh. Well. Don't tell the egg people. Let them enjoy it while they can."] },
      banar: { say: ["Your creatures get in at the edge, where it's less hot. They come out red, happy and very sleepy.",
                     "One of them licks its paw and makes a face. It tastes sweet."] },
    } },

    "e2-fogarin": { who: { fogarin: "Fogarín" }, nodes: {
      a: { say: ["It's late. The great forge is dark, except for one corner. There, with a small bellows and a furnace the size of a pot, the apprentice blows a glass tube as thin as a finger.",
                 "Don't tell the master. I use the leftover coal. I'm not stealing anything. Well, the coal.",
                 "He takes the tube out of the fire and dips it in a bucket of cold water. The glass makes a sound: a clean, long note, like a tiny bell."],
           opts: ["“What is that?”", "“That's what the Water girl told you.”", "Give him the shard with the black vein", "“I'll help. What do you need?”", "“Show it to Tizón.”", "“Be careful. If they catch you, they'll throw you out.”"] },
      que: { say: ["A tube that sings. The matriarch's don't sing, they swallow. This one sings when you cool it.",
                   "I had an idea. If a tube that swallows knows where there's sap, one that sings must know where the Root is. Because the Root sings too, right? So they say. If you lower it into a well and the note changes, you're close."] },
      agua: { say: ["Yes. Junco. Well, a friend of Junco's, from the Tides. She worked here two months and left without saying goodbye. She left me that and nothing else.",
                    "I don't talk much. The master says whoever blows doesn't give opinions. But I think. A lot. And this is what I thought."] },
      veta: { say: ["Fogarín takes the piece of black glass. He holds it up to the fire. He brings it near his singing tube.",
                    "The tube's note changes. It drops. It goes hoarse, like a sick throat.",
                    "Did you hear? It heard it! The glass knows. Now I have something to compare it with.",
                    "He gets to work as if you weren't there. By dawn he has three tubes, and each sings differently depending on how close it is to the black glass."] },
      ayudar: { say: ["You work the bellows. I can't blow and watch the glass at the same time.",
                      "You pump all night. Your arms burn. By dawn, Fogarín has a tube that sings one clean note, and another, deeper one, when you point it at the ground.",
                      "Pointing down it sings differently. Towards the Heart. You keep it, I've nowhere to hide it."] },
      tizon: { say: ["To the master? If I show him, he'll see it as a toy. Or worse: he'll want to sell it.",
                     "Well. Maybe you're right. The master isn't bad. He's just tired of being poor.",
                     "The next day Tizón sees it. He says nothing. That night, in Fogarín's corner, a sack of good coal appears that nobody stole."] },
      cuidado: { say: ["I know. But if I don't do it, nobody will. Nobody asks the one who blows anything.",
                       "He puts another tube in the fire. He doesn't ask you to leave, or to stay."] },
    } },

    "e2-miga": { who: { miga: "Miga, baker" }, nodes: {
      a: { say: ["In the bakers' street there's a queue that goes round the block. Miga, the baker who baked on the floor, no longer lights a fire: she lays the dough on the street's flagstones and it bakes by itself.",
                 "Earth bread! Free for whoever brings their dough! I don't pay for firewood anymore, Caretaker. The earth bakes for me!",
                 "The bread comes out golden and smells heavenly. People eat it in the queue, hot, with their eyes closed."],
           opts: ["Try a loaf", "“How hot does the flagstone get?”", "“Miga, Albor's flour… does it still come?”", "Buy a basket for the Ford", "Tell the queue the heat comes from the sap"] },
      probar: { say: ["It's the best bread you've ever eaten. Fluffy, warm. Too sweet, maybe. As if it had honey in it, but Miga doesn't add honey.",
                      "After a while you're very thirsty. And a little sleepy."] },
      losa: { say: ["In winter, nothing. Now, like a well-stoked wood oven. And it never cools. Not even at night.",
                    "At first it scared me. Then I did the sums. This month I saved six months of firewood. My daughter is going to the Meadow school. Do you know what that means?"] },
      harina: { say: ["No, thanks to you. I don't depend on Albor anymore. Now I buy Forest flour, which is cheap because there's fruit and grain everywhere.",
                      "Everything's going well this year, Caretaker. Sometimes I pinch myself."] },
      canasta: { say: ["Miga fills a basket with twelve loaves and charges you for nothing but the dough.",
                       "In the Ford, your neighbours eat them in no time. That night everyone sleeps very deeply. The next morning, nobody remembers what they dreamed."] },
      avisar: { say: ["You climb onto a bench and say it. The queue listens. Some stop chewing.",
                      "And what do you want me to do? Pay for firewood again? Have my daughter not go to school?",
                      "Nobody leaves the queue. A lady offers you a piece of her bread, to calm you down.",
                      "Don't be cross, Caretaker. If it's true, we'll see. But today there's bread."] },
    } },

    "e2-remache": { who: { remache: "Remache, clerk", fragua: "Master Fragua" }, nodes: {
      a: { say: ["In the Guild storehouse, the clerk is glued to an account book with a magnifying glass. He has ink even on his ears.",
                 "Caretaker. Good that you've come. You're not of the Guild or the Houses. I need someone who belongs to nobody to look at this.",
                 "He points to two columns. One says “House Destello: 200 tubes”. The other, in another clerk's hand, “House Alba, House Orza, House Brasa: 600 tubes. Delivery by the north tunnel.”"],
           opts: ["“Six hundred more? For the old Houses?”", "“Who signs those orders?”", "“Tizón delivered a hundred and ninety, not two hundred.”", "Copy both pages", "Burn the old Houses' orders", "Sell the information to the matriarch"] },
      casas: { say: ["The old Houses haven't been allowed to open wells since the Albor business. But if they buy tubes and bury them through the north tunnel, who's going to see?",
                     "The matriarch thinks she's the only one digging. She isn't. Half of what comes out of the earth is taken by people who didn't even bother to promise anything."] },
      quien: { say: ["Master Fragua. The Guild master. With his seal.",
                     "He's no thief, if that's what you think. Fragua keeps nothing. He shares what's left over among the smiths. It's what he always said: “Fire doesn't choose its customer; Fire eats from whoever pays.”",
                     "The trouble is that now both of them pay, and the Root doesn't bill just one."] },
      tizon: { say: ["A hundred and ninety? Then ten are missing… No: the ten that “broke”. I see. Good for Tizón.",
                     "But look here: the Houses' six hundred, nobody breaks those. Fragua makes those with his own hands, at night."] },
      copiar: { say: ["You copy both pages into your notebook, letter by letter, with the seals drawn in. Remache corrects your numbers.",
                      "Now there are two copies. If something happens to me, yours remains. That's all a clerk can do: make sure the truth doesn't depend on one person.",
                      "On the way out, you pass a big man in a leather apron coming in. He doesn't look at you. Remache slams the book shut."] },
      quemar: { say: ["You tear out the page with the six hundred and throw it in the brazier. Remache cries out and then covers his mouth.",
                      "What's going on here?",
                      "A big man in a leather apron full of burns is in the doorway. He looks at the brazier. He looks at your hand. He doesn't need to ask anything else.",
                      "Papers burn, Caretaker. Orders don't. The Houses have a memory and so does the Guild."] },
      vender: { say: ["To the matriarch? Well… yes. She'd stop it. Or at least take the business away from the old Houses.",
                      "Destello pays you well for the copy. A week later, Master Fragua is no longer Guild master. She picks the new master.",
                      "The six hundred tubes are still being made. Now they all go to House Destello."] },
    } },

    "e2-guijo": { who: { guijo: "Guijo", madre: "Guijo's mother", brida: "Brida, forewoman" }, nodes: {
      a: { say: ["On the slope, a woman is putting fresh mud on a skinny boy's arms. The boy with the hammer has shot up all at once. He has new burns from his wrists to his elbows.",
                 "He works in the Blind Wells, down below. They pay him double what the forge does. Double the silver, double the burns.",
                 "It's not that bad, mum. It's just hot down there. Like an animal. The walls breathe."],
           opts: ["“The walls breathe?”", "Heal his arms with your creatures", "Give him your Wells token so you go in his place", "Pay his mother what he earns in a month", "Go and talk to Brida"] },
      respiran: { say: ["Yes. You put your hand on them and they move, slowly. Up and down. The old ones say it's the heat. I think something's sleeping.",
                        "Sometimes, when we dig, it grumbles. Like when you touch a sleeping dog's belly. But it doesn't wake. Not yet."] },
      curar: { say: ["Your creatures lick his burns. One of them curls up in his lap. Guijo laughs for the first time.",
                     "Thank you. But tomorrow he goes down again. And the day after. You heal this once and the earth burns it every day."] },
      ficha: { say: ["You give him your wooden token, number 312. He gives you his. His is number 41 and worn from being clutched so much.",
                     "And what are you going to do down there?",
                     "You don't know yet. But number 41 goes in through the south tunnel tomorrow, and number 41 is going to be you.",
                     "I don't know who you are. But tonight my son sleeps up here."] },
      pagar: { say: ["A month? And the month after?",
                     "She accepts. Guijo doesn't go down to the Wells this month. He spends his days hammering nails in Tizón's forge, for half the silver.",
                     "It's boring. But it doesn't hurt."] },
      brida: { say: ["You find Brida at the mouth of the south tunnel, writing down names.",
                     "Guijo? He's one of the good ones. Digs fast and doesn't complain.",
                     "I told you that if something happened down there, I'd warn you. I'm warning you: the walls of tunnel nine are warm as skin. I don't send kids there anymore. I send the ones who volunteer.",
                     "She crosses Guijo's name off the tunnel nine list. She puts it on the one for tunnel three, which is cold."] },
    } },

    "e2-fragua": { who: { fragua: "Master Fragua", tizon: "Master Tizón" }, nodes: {
      a: { say: ["The Guild master receives you in the biggest forge in the Crater. He's an enormous man, in a leather apron with more burns than leather. He talks without stopping his hammering.",
                 "My name is Fragua. I know who you are. The whole Crater knows who you are. You're the one who paid Tizón when nobody paid him. That does you credit.",
                 "Now I'm going to tell you something you won't like, and then you'll tell me if I'm still the villain."],
           opts: ["“Go on.”", "Put the copy of the orders on the anvil", "“Why don't you hold the Night of Embers?”", "“I have nothing to say to you.”"] },
      cuente: { say: ["For forty years, Fire made Albor's tubes and Albor paid us half. My father died with black lungs making glass for people who didn't know his name.",
                      "Now everyone wants tubes. Destello, the old Houses, even the Forest folk ask. For the first time Fire sets the price. And you come to tell me not to sell them.",
                      "I'm not a fool. I know what the tubes do. But if I don't make them, someone else will, cheaper and worse. And Fire goes back to eating scraps."],
                opts: ["“Then make them worse, on purpose.”", "“Go into partnership with me. Let the profit be good for something.”", "“You're still the villain.”"] },
      peor: { say: ["Worse? So they break? Like Tizón's ten?",
                    "He puts down the hammer. He laughs, a big laugh that makes the glass tremble.",
                    "Tizón thinks nobody noticed. I count the broken glass, Caretaker. It's my job. And I said nothing.",
                    "Fine. If Tizón breaks ten, I can break a hundred. A broken tube swallows nothing. And the old Houses know nothing about glass."] },
      socio: { say: ["Partners? The Caretaker with the Guild? I didn't see that coming.",
                     "Deal. Part of what comes out goes to your Ford. You decide what it's spent on. That way at least something good comes out of this furnace.",
                     "He shakes your hand. His palm is so hard it feels like leather. The tubes go on being made."] },
      malo: { say: ["Maybe. But the villain feeds two hundred families. How many do you feed?",
                    "He doesn't wait for an answer. He goes back to the anvil. The conversation ended when he decided it did."] },
      libro: { say: ["Fragua sees the copy. He recognises his own seal drawn by your clumsy hand. He stops hammering.",
                     "Remache. Always honest, the wretch. That's why I put him there.",
                     "What do you want? Take it to the matriarch? She throws me out of the Guild and keeps it all. To the Houses? They pay me so nobody sees it.",
                     "Or you tear it up, and I ask you for something in return."],
             opts: ["“Stop the old Houses' six hundred, and I'll tear it up.”", "“I won't tear it up. But I won't show it as long as you don't make one more.”"] },
      parar: { say: ["Six hundred tubes. A winter's food for the Guild.",
                     "A long silence. Then he takes your copy, looks at it and hands it back untorn.",
                     "No. Keep it. I'll stop the six hundred. But I want someone to have proof that one day Fire chose to lose money. Because nobody will believe it."] },
      guardar: { say: ["An honest blackmail. That's new.",
                       "Fine. Not one more for the old Houses. What I've already made is made. Not even your notebook fixes that."] },
      ascuas: { say: ["The Night of Embers? The grandparents' one? Put out the Crater for a night, with three months of orders?",
                      "Tizón, who was listening at the door, comes in.",
                      "My father did it. Yours did too, Fragua. We laughed at them both.",
                      "And they both died with black lungs, Tizón. Is that what you want?",
                      "I want the ground to stop being hot. My grandson plays on that ground."],
              opts: ["“One night. Just one. If nothing happens, I won't ask again.”", "Let them argue it out"] },
      una: { say: ["Fragua looks at the fire for a long time, the way you look at an old dog that has to be put down.",
                   "One night. The night of the first frost. If the Houses ask, I said it was to clean the furnaces.",
                   "Thank you, Fragua.",
                   "Don't thank me. If nothing happens, you'll laugh at yourself all your life, like we laughed at our fathers."] },
      discuten: { say: ["They argue until the furnace goes out. In the end they decide nothing. But Tizón leaves with the face of someone who has already decided alone."] },
      irte: { say: ["As you like. Fire's door is open. My father couldn't have said that."] },
    } },

    "e2-ascuas": { who: { tizon: "Master Tizón", fogarin: "Fogarín", guarda: "Matriarch's guard" }, nodes: {
      a: { say: ["It's the night of the first frost. One by one, the Crater's furnaces go out. The chimneys stop smoking. For the first time in years, you can see the stars over the Crater.",
                 "My father said you had to listen. That on the Night of Embers the earth spoke. I never heard anything. I was little and I was bored.",
                 "In the middle of the forge square a single fire remains lit, a small one, in an iron brazier. Around it, a few smiths, in silence, with blankets."],
           opts: ["Sit by the brazier and listen", "Point the singing tube at the ground", "Ask who didn't come"] },
      quien: { say: ["Half of them. Those with orders from the Houses. Those who don't believe. Those afraid the matriarch will find out.",
                     "But Fogarín came. And the baker came. And old Ascua came, who never misses anything."] },
      escuchar: { say: ["At first you only hear the wind. Then, far below, something. It isn't a sound: it's the absence of a sound that was always there, like when a clock stops.",
                        "The ground cools under your hands. Slowly. Very slowly. And in the silence, from very far away, as if from the bottom of a well, a long breath. Someone who had been holding their breath and at last lets it go.",
                        "Did you hear that?",
                        "Tizón cries without a sound. He's sixty years old and he cries like a boy who understands something too late."],
                  opts: ["Stay until dawn", "Go out and watch the road"] },
      tubo: { say: ["Fogarín passes you the tube. You point it at the ground. It sings a low, hoarse note. Then, as the night goes on and the ground cools, the note rises. It clears.",
                    "Hear that? It's getting better. With just one night. One night and it already sings differently!",
                    "Imagine one night a week. Or a month."] },
      quedarse: { say: ["You spend the night around the brazier, without talking. At dawn, the first smith to light his furnace does it slowly, as if asking forgiveness.",
                        "Next year we do it again. Even if they throw me off the Council.",
                        "And if one day we have to be in the Heart, Fire will be there. Not for you anymore. For what we heard."] },
      guardas: { say: ["On the road down there are torches. A group of the matriarch's guards is coming up towards the Crater.",
                       "The matriarch asks why no tubes are coming out tonight. There's an order running late.",
                       "Behind you, the Crater's silence. Ahead, the torches."],
                 opts: ["Don't let them through", "Make up a furnace breakdown"] },
      pelea: { say: ["You plant yourself in the middle of the road. Your creatures stand beside you. The guards hesitate, and then they don't.",
                     "When it's over, the torches are on the ground. Above, the Crater is still silent. Nobody found out there was a fight."] },
      mentira: { say: ["A breakdown? In every furnace at once?",
                       "He looks at you. He knows you're lying. But he's cold and the climb is long.",
                       "I'll tell the matriarch tomorrow. Tomorrow without fail."] },
    } },
  });

  add("forest", {
    "e2-agalla": { who: { agalla: "Dame Agalla" }, nodes: {
      a: { say: ["The old oak in the clearing is so laden with acorns that two of its branches have broken. On the ground, a brown carpet. Some acorns have split open and are black inside.",
                 "Don't step on the black ones, they splash. I know. You don't need to tell me.",
                 "The voice comes from the trunk, slowly, as if each word had to climb up from far below."],
           opts: ["“Does it hurt?”", "“Why so much fruit?”", "“You had a hollow in your trunk.”", "Cut a healthy branch to graft far away", "“I'll tell the Council.”", "Gather the black acorns and bury them far away"] },
      duele: { say: ["It hurts the way giving too much hurts. Like when a mother has little and gives everything, and the next day can't get up.",
                     "It isn't the sap that hurts. It's what the sap asks of the soil. This year the Forest is eating next year."] },
      fruta: { say: ["Because the earth is full of something sweet that isn't ours. And we trees are foolish: if there's food, we eat. If there's a lot, we give a lot.",
                     "The young ones are happy. I'm four hundred years old, Caretaker. I've seen a year like this. The next one, not an oak was left standing in the whole north."] },
      hueco: { say: ["I had one. It closed by itself, after you came by. I thought it was a good sign.",
                     "It wasn't. It closed because the wood grew all at once, the way everything grows this year. Now I have a scar where I used to have a door."] },
      injerto: { say: ["Look for the north branch. The one that gives little fruit. That one is still mine.",
                       "You cut it carefully. Inside it's white, clean. You wrap it in damp moss.",
                       "Take it to the Ford. Plant it where nothing sweet reaches. If something happens to me, let something of me remain that hasn't eaten of this."] },
      concejo: { say: ["The Council. Good. Tell them old Agalla says so. Maybe they still listen to me.",
                       "Though I doubt it. This year the fruit speaks louder to them than I do."] },
      enterrar: { say: ["You gather black acorns all afternoon, with a shovel and a bag. You bury them far from the oak, in a deep pit, in rock.",
                        "The next day, where you buried them, a black shoot a hand tall has come up.",
                        "You can't bury what grows, Caretaker. But thank you. Good intentions feed something too."] },
    } },

    "e2-yedra": { who: { yedra: "Yedra", comprador: "Meadow buyer" }, nodes: {
      a: { say: ["On the Forest road there's a new market. Wooden stalls, carts from the Meadow, people haggling. In the middle, in a hammock strung between two posts, the woman who never kept the Long Silence runs everything without getting up.",
                 "Apples, two a sack! Acorns for the Houses' pigs! Caretaker, come here, I've got a price for you.",
                 "A Meadow buyer loads sacks onto a cart. He pays with new coins, the ones with Destello's seal."],
           opts: ["“Business is good, by the look of it.”", "Buy cheap fruit", "“The branches have black veins inside.”", "Help load the carts", "Ask the buyer what they want so much for"] },
      bien: { say: ["Good? For the first time in history the Forest asks nobody for anything. The other way round: the Meadow comes to buy from us. Do you know what that means?",
                    "My grandmother went to the Meadow to sell baskets and they made her wait at the back door. Now their grandchildren wait at my door."] },
      comprar: { say: ["Yedra fills a sack to the top for you. The apples are huge. Your creatures eat until they fall asleep in the cart."] },
      venas: { say: ["So what? The apples taste good. The pigs get fat. The Meadow folk pay.",
                     "Look, Caretaker. If the fruit is bad, there won't be any next year. I know. That's why I'm selling everything now, at today's price. When winter comes, I'll have money. The Council folk will have rotten apples in the granary.",
                     "She doesn't say it with malice. She says it like someone who has already done the sums."],
             opts: ["“Keep some of the money for those who won't have any.”", "“You're selling poison.”"] },
      guardar: { say: ["For those who won't have any? The Council folk, who glared at me for not keeping quiet in the Silence?",
                       "She sways in the hammock for a long time.",
                       "Fine. One coin in ten. In a box. Let nobody say Yedra didn't think of winter."] },
      veneno: { say: ["Poison? Everybody eats it and nobody's died.",
                      "What's she saying? Poison? Are you selling me poison?",
                      "The buyer unloads the sacks. Other buyers watch. In ten minutes, half the market is giving fruit back. Yedra looks at you from the hammock the way you look at a storm.",
                      "Thank you, Caretaker. This winter, when the Forest goes hungry, remember you took from me too."] },
      cargar: { say: ["You load sacks all afternoon. Yedra pays you with two new coins and a perfect apple.",
                      "You work well. If you get tired of minding critters, there's a place for you here."] },
      comprador: { say: ["What for? For everything. The Houses make jam, wine, fatten pigs. The matriarch wants to hand out fruit in the Quarter. You never see a year like this.",
                       "And it's cheap. The Forest was always cheap. That's why we come."] },
    } },

    "e2-bruma": { who: { bruma: "Bruma", abrojo: "Abrojo, Hedge guard" }, nodes: {
      a: { say: ["At the edge of the Forest, where the dry Hedge begins, there's a little log house with smoke from the chimney. At the door, the Shadow father who lived outside the Forest is splitting wood. He has a grey ribbon sewn on his coat.",
                 "Look what they gave me. “Hollow, the mill house.” The mist ate my mill when I was twelve.",
                 "Inside the house, two children play with pine cones. They speak with the Forest accent, not the Court one."],
           opts: ["“When do you have to leave?”", "“You helped me, last year.”", "“Hide in the Forest. I'll talk to the Council.”", "“Come to the Ford.”", "Walk them through the gap in the Hedge", "“Maybe the Hollow is better than you think.”"] },
      cuando: { say: ["Before the first frost. Two weeks left. Abrojo told me the Council won't object. The Council never objects to the Houses: it sells them fruit.",
                      "My children were born here. For them the Forest is home. The Hollow is a place their father talks about when he's sad."] },
      ayuda: { say: ["I helped you and you helped me. We're even. You owe me nothing.",
                     "Though, if you're going to owe me something, let it be this: that someone knows a Shadow family lived here twenty years and nobody in the Forest complained. Let that be kept somewhere."] },
      esconder: { say: ["You go to see Abrojo. You find him cutting dry branches off the Hedge.",
                        "Hide them? The Council asked me for a list of the Shadow folk living in the Forest. I've already handed it in.",
                        "But Bruma's little house… I forgot it. It's so small you can't see it from the road.",
                        "He doesn't look at you. He keeps cutting."] },
      vado: { say: ["To the Ford? With the Court folk, the Meadow folk, the Water folk, all together?",
                    "Well. My children already talk like the Forest. If they live in the Ford they'll talk like everyone. Maybe that's the best thing that could happen to them.",
                    "They load a cart with the firewood and the children. In the Ford, your neighbours make room for them without asking much. That's the Ford for you."] },
      seto: { say: ["You walk them to the gap you opened in the Hedge. On the other side, the road to the Underside is long and grey.",
                    "There. If we have to go, better to go with someone who isn't made to.",
                    "The children cross first. The youngest turns and waves to the Forest. Bruma doesn't turn round."] },
      mejor: { say: ["Maybe. Everyone says it's cured. That the mist doesn't eat anymore.",
                     "But I remember how the mill sounded before the mist ate it. If it sounds like that when I get there, I'll stay. If it doesn't, I'll come back. Permit or no permit."] },
    } },

    "e2-concejo": { who: { liquen: "Grandpa Liquen", yedra: "Yedra", concejal: "Forest councillor" }, nodes: {
      a: { say: ["The Forest Council meets around a huge stump. There are more people than ever: this year everyone has something to say, because everyone has something to sell.",
                 "The Houses offer to buy all the surplus harvest. In exchange, the Forest is left out of the Law of Return: the Shadow folk living here may stay. Let's vote.",
                 "I say we store it. Granary full. The coming winter will be long.",
                 "And I say the old man is afraid of a winter nobody but him has seen. Let's sell!"],
           opts: ["Vote to store the harvest", "Vote to sell to the Houses", "Propose sending the fruit to the Heights, who come down hungry", "“The fruit has black veins. Has anyone opened it?”"] },
      venas: { say: ["You open an apple in front of everyone. The core is black, glossy. A murmur runs round the stump.",
                     "Then let the Houses' pigs eat it. Better them than us.",
                     "Some laugh. Liquen doesn't. Neither does Yedra."] },
      guardar: { say: ["The vote is very close. In the end, storing wins by three votes. The Houses don't buy. The Law of Return still applies to the Forest.",
                       "Thank you. The granary will be full of bad fruit, and maybe it'll be good for nothing. But whoever reaches winter with something stored at least gets to choose what to throw away.",
                       "Yedra leaves before the meeting ends. Several of the Shadow folk who lived in the Forest start gathering their things."] },
      vender: { say: ["Selling wins by a lot. The Houses send carts that same week. The Forest is left out of the Law of Return. The Shadow folk may stay.",
                      "See? Everyone wins. Even the Shadow folk.",
                      "Everyone wins this year. Ask me next year."] },
      altos: { say: ["To the Heights? For free? They never gave us anything.",
                     "They gave us the wind that brings the rain, every year, without charging. As far as I know.",
                     "The argument goes on until night. In the end something odd is decided: half for the granary, half for the Heights. Nothing for the Houses.",
                     "Now they really will glare at me in the Meadow. Well. They already did."] },
    } },

    "e2-cripta": { who: { llovizna: "Llovizna" }, nodes: {
      a: { say: ["The Forest's roots have grown so much this year that they've pushed the stone door of the Crypt. Now it's ajar, a hand's breadth. A warm air comes out that smells of overripe fruit.",
                 "The Council says nobody goes in. That's why I came. Shall we go in?",
                 "Llovizna has a candle and the usual spoon in her pocket. She's scared stiff and she isn't leaving."],
           opts: ["Go in with her", "Go in with your creatures and have her wait outside", "Close the door again"] },
      entrar: { say: ["Inside there's a round room. Roots cover the walls like veins. Among them, tablets of hard wood, nailed into the stone, side by side. Hundreds.",
                      "On each tablet there's a drawing cut with a knife: a tree laden with fruit. Under the tree, lines. And beside some, a different mark: a bare tree.",
                      "They're years. Each tablet is a year. The Forest's grandparents counted them."],
              opts: ["Count the tablets", "Copy the tablets into your notebook", "Touch the roots on the walls"] },
      esperar: { say: ["Wait outside? Me? I found the door open.",
                       "But she waits. You go in with your creatures. Inside there are hundreds of tablets nailed into the roots. You glance at them quickly, without understanding, and come out with one in your hand.",
                       "What is it? Let's see… it's a tree with fruit. And next to it, a bare tree. What does it mean?"] },
      contar: { say: ["Llovizna counts with her spoon. You write it down. It takes hours. Every time there's a very laden tree, the next tablet has a bare tree. Always.",
                      "And every time there's a bare tree, underneath, on the same tablet, there's a tiny drawing: a figure with open hands, facing a circle.",
                      "Someone singing. Every time the Forest died, someone sang. And after?",
                      "After, the next tablet has an ordinary tree. Neither laden nor bare. And forty, fifty tablets later, a laden tree again."] },
      copiar: { say: ["You copy twenty tablets, the clearest ones. A laden tree, a bare tree, someone singing. Over and over.",
                      "It repeats. Like the lullaby. Like everything.",
                      "On the way out, the stone door closes by itself behind you, pushed by the roots. A hand's breadth less than before."] },
      raices: { say: ["The roots are warm. They beat. Slowly, once every long while, like a very big, very sleepy heart.",
                      "Llovizna puts her hand next to yours. She stays still for a long time.",
                      "It's hungry. I know because when I'm hungry mine beats like that."] },
      cerrar: { say: ["You push the stone door. Llovizna helps you, cross. It shuts with a dull thud.",
                      "Grown-ups always do that. They close what scares them and go to sleep.",
                      "That night, the roots push again. By dawn, the door is open once more."] },
    } },

    "e2-llovizna": { who: { llovizna: "Llovizna", liquen: "Grandpa Liquen" }, nodes: {
      a: { say: ["Llovizna is waiting for you on the road with a packed bag. She has her spoon hanging round her neck on a cord.",
                 "I'm going to the Meadow. To the Quarter choir. They pay half a ration for singing, and I sing nicely. Everyone says so.",
                 "Grandpa Liquen says no. He says the choir is a trap. But Grandpa says everything's a trap."],
           opts: ["“Why do you want to go?”", "“The choir doesn't exist anymore. We sabotaged it.”", "“I'll go with you. Go, but not alone.”", "“Stay. The Forest needs you here.”", "“Come to the Ford. There you sing without being paid.”"] },
      porque: { say: ["Because in the Forest everyone treats me like the girl with the spoon. And I found the tablets, and put my ear to the root, and nobody believes me.",
                      "In the choir, at least, they'll hear me."] },
      sabotaje: { say: ["You sabotaged it? They told me they made another one. Bigger. In the Tower square. With two choir mistresses instead of one.",
                        "She says it without malice. Knocking it off one stage only put it on a higher one."] },
      acompanar: { say: ["You walk with her to the Meadow. At the door of the new choir, the mistress looks her up and down.",
                         "Llovizna sings. She sings the Forest song, the one sung in the Long Silence. It isn't a lullaby. The mistress frowns. The stage lantern doesn't shine any brighter. But three Quarter children stop singing to listen to her.",
                         "They didn't want me. They say my song doesn't make light.",
                         "She says it happily."] },
      quedarse: { say: ["It needs me? What for? To pick bad fruit?",
                        "To remember, child.",
                        "Grandpa Liquen is behind a tree. He heard everything.",
                        "I'm forgetting things. The Forest I came from, how the lullaby used to be. If you go, who remembers after me?",
                        "Llovizna puts the bag down on the ground. She says nothing. She sits down next to her grandfather."] },
      vado: { say: ["To the Ford? With you? To look after creatures?",
                    "Yes! Well. But on Sundays I come back to see Grandpa. And I'm bringing the spoon.",
                    "In the Ford, Unísona listens to her sing the Forest song. At the end, it sings along with her, one note higher. The first time you've heard it sing in weeks."] },
    } },

    "e2-raices": { who: { abrojo: "Abrojo, Hedge guard", liquen: "Grandpa Liquen" }, nodes: {
      a: { say: ["Abrojo and Grandpa Liquen have dug a pit at the foot of the dry Hedge, as deep as a man is tall. They call you over to see the bottom.",
                 "Down there, the Hedge's roots are thick as arms and swollen. Outside, brown. Inside, when Abrojo cuts one, black sap comes out, thick. A lot of it.",
                 "I planted a wall and a mother grew. The Hedge isn't dying of anything. It's dying of swallowing.",
                 "It's drinking the sap before it reaches the Forest. That's why it dries. What's above dies so what's below can hold."],
           opts: ["“How long has it got?”", "“Let it be. Let it keep drinking.”", "“Cut the roots. Don't let it die for us.”", "Ask Unísona to sing to it", "Plant Agalla's graft by the Hedge"] },
      cuanto: { say: ["One winter. Maybe two. Then it dries out completely and the sap goes on past.",
                      "And then this year's fruit will look like a joke. The whole Forest will be like those acorns."] },
      dejar: { say: ["Let it. It's doing what a mother does. It isn't fair, but it's what it does.",
                     "They fill in the pit again. Above, the Hedge drops another dry branch.",
                     "I'll tell the Council not to cut any more. To let it die in peace."] },
      cortar: { say: ["Abrojo hesitates. Then he cuts. One root, two, five. The black sap gushes and trickles towards the Forest, seeking a way between the stones.",
                      "The next day, the Hedge puts out green leaves. Very green. And in the Forest, by the road, the apple trees wake with the fruit rotten on the branch.",
                      "You saved the Hedge's life. And you passed the bill to the Forest. It's always like that, Caretaker: somebody pays the bill."] },
      cantar: { say: ["Unísona goes to the edge of the pit. It looks at the black roots. Then it sings. It isn't the lullaby: it's something lower, slower, like the purr of a big animal.",
                      "The roots stop beating so fast. The sap coming out of the cuts turns clearer, slower. It doesn't heal. It sleeps.",
                      "I never heard a creature sing to a tree.",
                      "I have. Once. Long ago, in another Forest. Before it died."] },
      injerto: { say: ["You plant Dame Agalla's white branch beside the Hedge, where the roots aren't swollen yet.",
                       "The branch stays still. It doesn't put roots down. It puts them out sideways, towards the Hedge's roots, and tangles with them.",
                       "It's helping. One passes the other what it has to spare. That's how old trees hold each other up, below, where you can't see."] },
    } },
  });
  /* ==================== Delivery 3: the Night (Grey Hollow, Mirror Lake, Echo Caves) ==================== */

  add("hollow", {
    "e2-cuna": { who: { orvallo: "Orvallo" }, nodes: {
      a: { say: ["At the door of a Court house, a man is rocking a wooden cradle. It's the same cradle that went down the Meadow road a year ago, carried on his back.",
                 "She doesn't sleep. Three weeks without sleeping more than an hour at a time. In the Quarter she slept like a stone.",
                 "The house casts no shade. The afternoon sun goes right through it as if it were glass. In the cradle, the baby has her eyes wide open, staring at the light."],
           opts: ["“Why doesn't she sleep?”", "“You took the cradle to the Quarter. Why did you come back?”", "Make shade for her with your cloak", "Ask Unísona to sing the Shadow lullaby", "“Take her to the Ford. There's real shade there.”"] },
      porque: { say: ["Because Court children sleep in the shade of the house. Not in the dark: in the shade. It's different. A house's shade is like an arm.",
                      "The houses here don't make any now. The mist went and took the shade with it. My daughter never saw the old Hollow, and still she misses it."] },
      volvio: { say: ["Because the Law says so, and because the room in the Quarter was lent. They gave us a cart, a blanket and a grey ribbon.",
                      "In the Quarter at least the neighbours sang. Here there are twenty families and nobody sings. It's shameful to sing in a house that casts no shade, like singing in a dead man's house."] },
      capa: { say: ["You spread your cloak over the cradle. Underneath, a tiny shade forms, the size of the baby.",
                    "The baby blinks. Yawns. A few minutes later she falls asleep with her fist in her mouth.",
                    "A cloak. Three weeks, and it was a cloak. Stay a while, please. If you go, the sun takes it."] },
      nana: { say: ["Unísona sits by the cradle and sings the dark half of the lullaby, the Shadow's. Very softly.",
                    "Nothing changes with the light. But people come out of the houses nearby. A woman starts singing with Unísona from her window. Then another. Then an old man, out of tune.",
                    "First time anyone's sung here since we came back. Look at her: she's asleep."] },
      vado: { say: ["To the Ford? Without a permit? If they find me without the ribbon where it should be, they'll take my Threshold permit for good.",
                    "But she sleeps. There, she sleeps. The rest we'll see.",
                    "He swings the cradle onto his back again. It's the third time in a year that cradle has crossed the Glade."] },
    } },

    "e2-tordo": { who: { tordo: "Tordo, Court letter carrier" }, nodes: {
      a: { say: ["The Court's old letter carrier climbs the slope with a bag so full he has to hug it. He sits on a stone to get his breath back.",
                 "There were never so many letters. The Law split families in half: some came back, others stayed up there with work permits. And they write. Every day.",
                 "I carry them. I can't read well, but I know whose hand each letter is. My name's Tordo, in case you don't remember. Nobody remembers the letter carrier."],
           opts: ["Offer to carry half the bag", "“Is there a letter you can't deliver?”", "“Did Penumbra's letter reach her in the end?”", "Read an open letter that fell out of the bag"] },
      llevar: { say: ["You carry letters all afternoon, door to door. Some people cry when they get theirs. One woman tears hers up without opening it.",
                      "That's from the husband who stayed up there. He writes every day. She tears them up every day. Both of those are love, Caretaker. Take it from me, forty years in this job."] },
      noentrega: { say: ["There are some. Letters from the ones who left in House Alba's carts. They're not from the Meadow or from here. They come with no address, with a strange seal.",
                         "He gives you one. The seal is a shovel crossed with a lamp. Inside, the handwriting is of someone who can barely write."],
                   opts: ["Open it", "Give it back unopened"] },
      abrir: { say: ["“Mum: I'm not in the Hollow. House Alba's carts didn't go to the bridge house. They took us down a tunnel. We dig at night. The walls are warm. They pay me, don't worry. Don't tell anyone where I am, because I don't know where I am. Your son, Grieto.”",
                     "Grieto. The son of the Ceniza family, from the bridge house. His mother waits for him down there, watching the road every day.",
                     "If I take her this, do I do her good or harm? Forty years and nobody taught me that."],
             opts: ["“Take it to her. She has a right to know.”", "“Keep it. I'll go and find that tunnel.”"] },
      entregar: { say: ["Tordo goes down to the bridge house. He's gone a long time. When he comes back, he isn't hugging the bag: it hangs at his side, as if it weighed less.",
                        "She cried. And then she put her coat on and went to the square to ask everyone about House Alba's carts. There are six mothers with her already."] },
      buscar: { say: ["You, find him? Good. Take the letter. If you find him, tell him his mother keeps his bed made.",
                      "You put the letter away. The shovel crossed with the lamp watches you from the seal."] },
      devolver: { say: ["Thank you. Sometimes not opening a letter is the only decent thing a person has left.",
                        "He puts it at the bottom of the bag, under all the others."] },
      penumbra: { say: ["I delivered it. Late, but I delivered it. She went back down to look for her street, did you know? With her embroidered ribbon.",
                        "I told her Loom Street doesn't exist anymore. She said: “Then I'll embroider it.” I don't know what she meant."] },
      leer: { say: ["“Pablito: up here there's light all night and I can't sleep. They say there's no mist down there anymore. Is it true the house casts no shade? Keep mine for me, even if it's in a jar. I love you. Mum.”",
                    "That one didn't fall. I let it fall, so someone else would read it. It weighs on me to carry it alone."] },
    } },

    "e2-cierzo": { who: { cierzo: "Cierzo, Throne guard", ceniza: "Ceniza" }, nodes: {
      a: { say: ["In the Throne room there's no king. Lóbrego moved to a tent in the square after confessing. But the Throne guard is still at his post, with his spear, guarding an empty chair.",
                 "My name is Cierzo. Forty years guarding this chair. The king left, but the chair is still the chair. Someone has to guard it.",
                 "Caretaker, you gave the king the courage to confess. And look what happened. Three names shouted in the Meadow. Families in carts. The mist gone. Tell me it was worth it."],
           opts: ["“It was. The truth isn't to blame for what they did with it.”", "“I don't know if it was.”", "“You burned the deed, last year.”", "“What do you propose?”"] },
      valio: { say: ["That's what people say who lost nothing.",
                     "But he lowers his spear a little.",
                     "My mother said the same as you. That the truth doesn't bite. My mother never saw a shadow with her name shouted."] },
      nosabe: { say: ["At least you tell the truth. That's more than the Meadow folk say."] },
      acta: { say: ["You burned it, if I remember right. Or I burned it so you wouldn't. I don't remember well anymore, and that worries me.",
                    "The king confessed anyway. No paper. With his mouth. Spoken words don't burn."] },
      propone: { say: ["That we go back to the veil. All of us. That no shadow ever says their true name again, not even to their mother. That we all call ourselves by what we do, as in the Wells.",
                       "That way nobody can shout a name. Because there'll be no names.",
                       "Behind a column, someone is listening. A young woman with her hood pulled low.",
                       "That's what Albor did to us. Called us by what we did. Now we do it to ourselves?"],
                 opts: ["Back Cierzo: the veil protects", "Back Ceniza: the name is what was won back", "“Let each one choose.”"] },
      velo: { say: ["Thank you. Tomorrow I'll propose it in the square. People are afraid. When they're afraid, they vote fast.",
                    "You'll see how fast we forget what we're called.",
                    "Ceniza leaves. Cierzo goes back to guarding the chair, calmer."] },
      nombre: { say: ["Thank you. Even if they shout it. Even if I have to go when they call.",
                      "You're young, girl. You'll learn.",
                      "You were young too when they taught you to be afraid. Don't forget it.",
                      "Cierzo doesn't answer. But that night, for the first time in forty years, he leaves the spear leaning against the chair and goes home to sleep."] },
      elegir: { say: ["Choose? The Court never chose anything. That's why it lasted six hundred years.",
                      "That's also why it was thrown out of two lands.",
                      "They argue all afternoon. In the end, in the square, that's what's decided: each one chooses. Half put on the veil. The other half don't. For the first time you can tell who is who."] },
    } },

    "e2-telar": { who: { penumbra: "Penumbra", calina: "Calina, mist weaver" }, nodes: {
      a: { say: ["At the far end of the Hollow, where the mist ate a street twenty years ago, there is now a field of stones. On it, sitting on a loom bench with no loom, the Shadow seamstress embroiders in the air.",
                 "Loom Street. My ribbon says I'm coming back here. So here I am. There's no street, but I'm here.",
                 "Beside her, the mist weaver hands her grey threads that come apart when touched. Together they're trying something that won't come."],
           opts: ["“What are you doing?”", "“You embroidered “Ford” instead of “Underside”. Why did you come?”", "Help them with the threads", "Sing the Shadow lullaby over the stones", "Look for something among the stones"] },
      que: { say: ["Sewing the street. If the mist won't come out of the ground, let it come out of us. She embroiders, I weave. Three days now.",
                   "It won't come. But it's the first thing I've made in years that isn't somebody else's name on a ribbon."] },
      vado: { say: ["Because the hundred and twelve people we embroidered had somewhere to go. I didn't. The Ford doesn't know me and I don't know the Ford.",
                    "And because someone has to come back and tell whether you can live here. Better an old woman than a family with children."] },
      ayudar: { say: ["You hold the threads while they work. They come apart all the same. But when night falls, between your fingers, one holds. Just one. Grey, warm, fine as a hair.",
                      "That one came from your hands, not ours. Hands from up there still keep some mist, from coming down so often.",
                      "Penumbra sews it onto the edge of her ribbon, next to her name."] },
      cantar: { say: ["You sing over the stones. Unísona sings with you. At first, nothing.",
                      "Then, between two stones, a low mist rises, ankle high. It stays there. It doesn't climb. But it draws, for a moment, the outline of a street: doors, steps, a loom.",
                      "There it was. The house in the middle was mine.",
                      "The Root doesn't sleep as deeply as they say. It remembers."] },
      buscar: { say: ["Among the stones you find a loom shuttle, worn, with initials carved in it. Penumbra recognises it before you hand it to her.",
                      "My mother's. Twenty years under the earth and the wood is warm.",
                      "She doesn't cry. She holds it the way you hold a hand."] },
    } },

    "e2-carros": { who: { agente: "House Alba agent", orvallo: "Orvallo" }, nodes: {
      a: { say: ["Three Law of Return carts arrive in the Hollow square. The families get down, with their ribbons. A man with a notebook and the crest of House Alba is waiting for them.",
                 "Men between fifteen and forty, to the left. There's paid work. Very well paid. Everyone else, to your houses.",
                 "Some go left gladly. Others look at their wives. A windowless cart waits behind, the horses restless."],
           opts: ["“What work?”", "Show Grieto's letter in front of everyone", "Stand in front of the windowless cart", "Follow the cart from a distance", "Sign up yourself, on the left"] },
      trabajo: { say: ["House works. Far from here. Food, a roof and double pay. Any problem?",
                       "Double. With double you can buy a house that casts shade.",
                       "Orvallo sets the cradle down. He takes a step to the left."] },
      carta: { say: ["You read the letter aloud. “They took us down a tunnel. We dig at night. The walls are warm.”",
                     "The square goes silent. The men on the left look at each other. One goes back to his family. Then another. Orvallo picks up the cradle.",
                     "That's a forgery. The Houses pay.",
                     "But the windowless cart leaves empty. The mothers who were asking about Grieto surround the agent."] },
      carro: { say: ["You plant yourself in front of the horses. The driver pulls on the reins. The agent closes his notebook.",
                     "Out of the way, Caretaker. This is a House Alba contract.",
                     "You don't move. The agent signals. Two guards climb down from the box."] },
      seguir: { say: ["You follow the cart from a distance. It doesn't go to any house in the Hollow. It goes to the bottom of the valley, where a new tunnel mouth, hidden under tarpaulins, opens in the rock.",
                      "The men get down. They go in. A warm air comes out of the tunnel that smells of overripe fruit. Above the mouth, painted on the rock, the same seal: a shovel crossed with a lamp."] },
      apuntarte: { say: ["You? Well, you've got arms. Into the cart.",
                         "You climb in. Inside it's dark and smells of fear. A boy beside you is clutching a grey ribbon between his fingers.",
                         "The cart goes down for a long time. When the door opens, you're in a gallery under the Meadow, facing a glass tube that beats. They give you a shovel and a number."] },
    } },

    "e2-llamada": { who: { ceniza: "Ceniza", lobrego: "King Lóbrego" }, nodes: {
      a: { say: ["It's night. From the square, someone shouts a name. Not “Ceniza”. The other one, the true one, the one the matriarch read from Albor's box.",
                 "Ceniza stands up. Her eyes are open but she looks at nothing. She walks to the door the way someone walks in their sleep.",
                 "They're calling me. I have to go. It isn't law. It's what we are."],
           opts: ["Stand in the doorway", "Ask Unísona to sing louder than the shout", "Go and see who's calling yourself", "Call her yourself by her true name, so she comes with you"] },
      puerta: { say: ["You stand in the doorway. Ceniza bumps into you and keeps pushing, slowly, without strength and without stopping, like water against a stone.",
                      "Let me go. It hurts not to go. It hurts like a burn.",
                      "You can't hold her all night. She knows it. So do you."],
                opts: ["Let her go and follow her", "Hold on until the shouting stops"] },
      aguantar: { say: ["You hold on. Ceniza pushes. The shout goes on, hoarser and hoarser. After an hour, it stops.",
                        "Ceniza falls to the floor, shaking, as after a fever. Her palms are burned from gripping your clothes.",
                        "Thank you. I don't know if you saved me or stole something from me. Both, I think."] },
      cantar: { say: ["Unísona sings. Not the lullaby: a long, high sound that fills the room. Ceniza stops.",
                      "The shout from the square goes on, but now there's something stronger on top of it. Ceniza blinks. She looks at you, at last.",
                      "I hear it. But it isn't calling me anymore. It's calling someone who looks like me.",
                      "Unísona doesn't stop singing until dawn. The next day it has no voice. But Ceniza is still in the room."] },
      quien: { say: ["In the square, under the window, there's a boy of about twelve with a sheet of paper in his hand. He reads the name aloud, letter by letter, because he can't read fluently.",
                     "Ceniza arrives behind you and stops in front of him, like someone waiting for an order.",
                     "Who gave you that paper, boy?",
                     "The king has come down from his tent, unveiled. The boy trembles.",
                     "“A gentleman from House Alba. He gave me a coin to shout it every night. He said it was a game.”"],
             opts: ["Take the paper and tear it up", "Give him two coins yourself so he doesn't come back"] },
      romper: { say: ["You tear up the paper. The boy runs off. Ceniza stands still, still waiting for the order that doesn't come.",
                      "They'll make another paper. And another. As long as that name is written in some House Alba box, she isn't free.",
                      "If you go to the Heart, Caretaker, the Court goes with you. Not for me anymore. For her."] },
      pagar: { say: ["The boy grabs the coins and leaves. Tomorrow House Alba will find another boy, but tonight the square is quiet.",
                     "You saved me for two coins. That's how cheap a name is here."] },
      llamar: { say: ["You say her true name. Softly. She turns to you, the way a plant turns to the sun.",
                      "She comes with you. She follows you inside. She sits where you tell her. The shout from the square doesn't move her anymore: someone else is calling her now.",
                      "See? I'm nobody's now. I'm yours. That isn't free either, Caretaker.",
                      "She says it without anger. She says it so you won't forget."] },
    } },

    "e2-niebla": { who: { calina: "Calina, mist weaver", cierzo: "Cierzo, Throne guard" }, nodes: {
      a: { say: ["This morning the Hollow woke with mist. Not much: a white veil rising from the ground up to the knees, breathing slowly, rising and falling.",
                 "People come out into the street barefoot. Some cry. The children born up there don't know what it is and hide.",
                 "It's back. Not all of it, but it's back. The Root is stirring in its sleep. Something is bothering it down there, under the Meadow, and it turns over in bed."],
           opts: ["“Then it isn't good news.”", "Collect mist in a jar", "Ask Calina to weave it over the houses", "Warn everyone that the Root is waking"] },
      mala: { say: ["No. But it's the only news we have.",
                    "My mother said the mist was the breath of a sleeping mother. If she breathes harder, she's waking. And mothers who wake hungry…",
                    "He doesn't finish. He doesn't need to."] },
      frasco: { say: ["You dip a jar into the mist and cap it. Inside, the white moves slowly, like a fish in a bowl.",
                      "Take it with you. If one day you sing in the Heart, let the Root smell its own breath. Maybe it'll remember it used to breathe calmly."] },
      tejer: { say: ["Calina weaves all afternoon. She combs the mist with her fingers and lifts it, thread by thread, up to the roofs. By nightfall, three houses have shade again.",
                     "One of them is Orvallo's. From the window comes the sound of a cradle rocking, and then nothing: a baby sleeping.",
                     "Three houses. It's almost a street. If the Court goes to the Heart one day, it'll go with shade of its own."] },
      avisar: { say: ["You go door to door. Some listen. Most are too happy to hear.",
                      "Don't take this from them, Caretaker. One morning. Leave them one morning.",
                      "At noon, the mist goes. People go back to their shadeless houses. But now they know it can come back, and that that isn't good news."] },
    } },

    "e2-pablito": { who: { nino: "Hollow boy" }, nodes: {
      a: { say: ["A boy of about eight is sitting on the step of an empty house, with a glass jar on his knees. The jar is empty. He caps it and uncaps it, over and over.",
                 "My mum asked me to keep the house's shade for her in a jar. She wrote it to me. But the house makes no shade. How do you keep something there isn't?"],
           opts: ["“Where's your mum?”", "Shade the jar with your hand and cap it quickly", "“Let's keep something else: your voice. Sing her something.”", "“It can't be done. I'm sorry.”"] },
      mama: { say: ["Up in the Meadow. She has a work permit. She cleans the Tower. I came with Grandma because Grandma's ribbon said I belonged here.",
                    "She writes to me every day. The letter carrier reads them to me because I can't read well yet."] },
      mano: { say: ["You put your hand over the jar. Under it a tiny shade forms. The boy caps the jar at once.",
                    "He holds it up to the sun. There's nothing inside. But he looks at it as if there were.",
                    "It's your shade, not the house's. But it's a shade. Mum won't notice."] },
      voz: { say: ["The boy thinks hard. Then he uncaps the jar, brings it to his mouth and sings, very softly, the Shadow lullaby. He gets it wrong halfway. He finishes anyway.",
                   "He caps the jar. He holds it against his chest.",
                   "If Mum opens it, she'll hear me. That's better than a shade, isn't it?"] },
      nopuede: { say: ["I know. I'll send her the empty jar anyway. So she knows I tried."] },
    } },
  });

  add("lake", {
    "e2-anea": { who: { anea: "Anea" }, nodes: {
      a: { say: ["On the jetty, the boat girl sits with her oars crossed. Ahead, the grey lake, smooth, without a reflection.",
                 "I can't go out. I used to steer by the sky in the water: I'd look down and see the clouds and know which way to go. Now the water has no sky. I row in circles.",
                 "Yesterday three boats got lost. They came back at night, by the sound of the jetty bells."],
           opts: ["Get in her boat and steer by the real sky", "Tie a rope from the jetty to the boat", "Ask a creature to swim ahead", "“Better not go out until the lake sees.”"] },
      cielo: { say: ["You sit in the bow with your head tipped back, watching the sky. Anea rows. You say “left”, “right”.",
                     "How strange to look up. We never look up. The real sky is very far away. The one in the water was close.",
                     "You reach the far shore. Anea learns fast. On the way back she steers."] },
      cuerda: { say: ["You tie a long rope, very long, from the jetty to the boat. Anea rows as far as the rope reaches and comes back.",
                      "It's like going out holding someone's hand. You don't get far, but you come back.",
                      "The next day, every boat at the jetty has a rope. The lake looks like a spider's web."] },
      nadar: { say: ["One of your creatures jumps into the water and swims ahead of the boat. Where it swims, the water moves, and where it moves, for an instant, a scrap of reflection appears.",
                     "There! There's sky there! When something moves, the lake remembers.",
                     "Your creature comes out shivering. But Anea now knows something nobody knew."] },
      quedarse: { say: ["And eat what? The Tides live off the lake. If the lake can't see, we still have to eat.",
                        "She crosses her oars again. She looks at the water. The water doesn't look at her."] },
    } },

    "e2-cardo": { who: { cardo: "Cardo, water seller" }, nodes: {
      a: { say: ["On the shore, the Meadow water seller fills barrels with a ladle. He has a cart with a new sign, painted in gold letters: WATER FROM THE CURED LAKE. CLEAN AS FORGETTING.",
                 "Caretaker! Want a glass? The Houses buy it by the barrel. They say it's the purest thing in the Glade. Tastes of nothing. Literally nothing.",
                 "He has more barrels than ever, and a Tide boy helping him for half of what the work is worth."],
           opts: ["Try a glass", "“Why “clean as forgetting”?”", "“Do you pay the Tides anything for the water?”", "Buy a barrel for the Ford", "Tip his barrels into the lake"] },
      probar: { say: ["It tastes of nothing. Not even water. It's like drinking cold air.",
                      "After a while, you try to remember what you dreamed last night and you can't. Nothing. As if someone had wiped that part clean."] },
      olvido: { say: ["That's what the people who drink it say. They sleep like babies and dream nothing. That's why the Houses want it: Meadow folk have had nightmares since the Night of Lanterns. With this, nothing.",
                      "I don't see the problem. Do you want to dream of black sap every night?"] },
      pagan: { say: ["Pay? For water? Water belongs to everyone.",
                     "Well. To the lake. Which belongs to the Tides. Who don't charge me because it never occurred to them.",
                     "He scratches his head. For the first time he looks uncomfortable."],
               opts: ["“Pay. Half, to Mother Marejada.”", "“It's none of my business.”"] },
      mitad: { say: ["Half? You'll ruin me.",
                     "But he counts on his fingers. A lot of counting.",
                     "A third. And they let me keep the sign. If the Tides charge, let the Tides sell too. That way at least what gets taken leaves them something."] },
      barril: { say: ["You take a barrel to the Ford. Your neighbours drink it. That night, for the first time in weeks, nobody wakes up screaming.",
                      "In the morning, Unísona doesn't recognise the neighbour next door. It looks at her like a stranger, and she at it. It passes by noon."] },
      volcar: { say: ["You tip the barrels into the lake. The water goes back to the water without a sound. Cardo shouts. The Tide boy laughs despite himself.",
                      "That was House Orza's order! Do you know how much…?",
                      "He looks at you. He looks at the lake. It's as still as before. It didn't care at all.",
                      "Not even the lake wants it back. Look at that."] },
    } },

    "e2-sargazo": { who: { sargazo: "Sargazo, who prays", orilla: "Orilla" }, nodes: {
      a: { say: ["At the end of the jetty, the praying old man has been on his knees for days. He doesn't eat. They brought him bread and he threw it in the water.",
                 "Orilla read it in the old notebook. “The lake did not reflect for three generations, until the Singer wept in it.” So someone has to weep.",
                 "Six days I've been trying. It won't come. I'm old and I wept all I had when my wife died."],
           opts: ["“Eat something. You can't force tears.”", "“Who was the Singer?”", "Ask Unísona to go near the water", "Sit with him, without a word"] },
      comer: { say: ["If I eat, I'll sleep. If I sleep, I won't weep. And the lake stays blind.",
                     "Grandpa, the notebook doesn't say weeping works. It says it happened. That's not the same.",
                     "For those of us who pray, it is the same, child."] },
      cantora: { say: ["The statue in the middle, in the Heart, they say. The one who sang first. I don't know more. The old pages are wet.",
                     "She was one of us. A Tide. I know that without a notebook. Only a Tide weeps into a lake to make it see."] },
      unisona: { say: ["Unísona leans over the edge of the jetty. It looks at the grey water for a long time.",
                       "Then it does something you've never seen it do: a drop of light falls from one eye. Just one. It falls into the lake.",
                       "Where it falls, the water opens in a ring. And in the ring, for an instant, there's a reflection: not of the sky, not of you. Of a stone woman with her mouth open, weeping.",
                       "There she is. There she is.",
                       "Sargazo weeps, at last. Like a child. The reflection is gone, but he weeps anyway."] },
      sentar: { say: ["You sit beside him. An hour passes. Two. The lake doesn't change.",
                      "At nightfall, Sargazo offers you half a loaf he had hidden in his pocket. He eats the other half.",
                      "At least I'm not praying alone. That's something."] },
    } },

    "e2-ola": { who: { ola: "Ola", fogarin: "Fogarín" }, nodes: {
      a: { say: ["In a workshop on the shore, a young Tide woman is cooling glass in the lake water. Each piece makes a different sound as it touches the water.",
                 "My name's Ola. I worked two months in the Crater forges, carrying coal. I left without saying goodbye because I was ashamed to be seen crying.",
                 "There I learned one thing: long glass, when you cool it, sings. Here I found out another: if you cool it in lake water, it sings what the lake can't see."],
           opts: ["“What does it sing?”", "“Fogarín makes tubes that sing. Because of what you told him.”", "“You wrote a letter you never sent.”", "Help her cool a piece"] },
      canta: { say: ["Ola dips a tube in the water. A low, trembling note sounds, rising and falling like breathing.",
                     "That's the Root sleeping. It dreams. When it dreams badly, the note breaks. Yesterday it broke three times. Last week, never.",
                     "Something is bothering it more every day. And it isn't here. It's further up."] },
      fogarin: { say: ["Fogarín? The bellows boy? He makes tubes?",
                       "She blushes to her ears.",
                       "I don't believe it. He never talked. I thought he wasn't listening to me.",
                       "If his tubes sing with fire and mine with water… together we could find out where it hurts. Tell him to come. No: tell him I'm coming."],
                 opts: ["“Let's go to the Crater together.”", "Take one of her tubes to him yourself"] },
      juntos: { say: ["You go down to the Crater together. In the corner of the forge, Fogarín looks up from the bellows and goes still, mouth open.",
                      "Ola.",
                      "Hello. I left without saying goodbye. Sorry.",
                      "They say nothing more for an hour. They put the tubes together. One of fire, one of water. When they point them towards the Meadow, both sing the same broken note."] },
      llevar: { say: ["You take one of Ola's tubes to the Crater. Fogarín looks at it a long time without touching it. Then he sets it beside his own.",
                      "They sing the same. She was right. She was always right.",
                      "He doesn't ask about her. But that night he puts out the furnace early and walks off towards the lake."] },
      carta: { say: ["How do you know that? Ah. You carried it. I remember now.",
                     "It was for my sister. I asked her to forgive me for leaving the lake. Now I've come back and she's gone to the Meadow on a work permit. We always cross paths."] },
      ayudar: { say: ["You dip a tube into the water. It sounds. The note is low, and in the middle it has a knock, like a hiccup.",
                      "Did you hear the knock? That's a new well. Every time they open one, the note gets another knock. Eleven now."] },
    } },

    "e2-berro": { who: { berro: "Berro", nasa: "Grandma Nasa" }, nodes: {
      a: { say: ["The boy with the stick is bringing something in a bucket. He drags it with both hands, proud and scared.",
                 "Look! I caught it all by myself. No hook. It let itself be caught.",
                 "In the bucket is a huge silver fish with no eyes. Where the eyes should be, the skin is smooth. It swims in circles, bumping the rim, calm."],
           opts: ["Look at it up close", "“Grandma Nasa, had you ever seen one like this?”", "Put it back in the lake", "Take it to Mother Marejada", "Let Berro eat it, like in the story"] },
      mirar: { say: ["It has no eyes, but it knows where you are. When you bring your hand near, it turns towards it.",
                     "Inside, through the scales, you can see a dark line running along its back. It isn't black. It's grey. Like the lake."] },
      nasa: { say: ["Not in my life. But my grandmother said that in the years without reflection, blind fish were born, because there was no need to see in a lake that shows nothing.",
                  "She said that if many were born, the lake would forget it ever had eyes. And then it would never see again."] },
      devolver: { say: ["Berro protests, but he helps you. The fish drops into the water and swims off, slowly, bumping into nothing.",
                        "Fine. I know where there are more. Lots more. Over there, where the water is warm."] },
      marejada: { say: ["Mother Marejada looks at the fish a long time. She lays her hand on its back.",
                        "The Mother who once saw tomorrow in the lake closes her eyes, as if she could see better that way.",
                        "“It's dreaming,” she says. “Fish dream what the lake dreams. And the lake dreams of the Root. This one dreams it's hungry.”"] },
      comer: { say: ["Like the one in the story? The one that makes you see tomorrow?",
                     "They cook it on the shore. Berro eats a bite. He goes very still. Then he cries.",
                     "I didn't see tomorrow. I saw nothing. All grey. Is tomorrow going to be like that?",
                     "No, my boy. That's how the lake is today. Nobody knows tomorrow. Not even the fish."] },
    } },

    "e2-orilla": { who: { orilla: "Orilla", marejada: "Mother Marejada" }, nodes: {
      a: { say: ["Orilla is waiting for you in Mother Marejada's house with the oilcloth notebook open on the table. She has dried the old pages in the sun, one by one, with clothes pegs.",
                 "I could read what was wet. You won't like it. I didn't.",
                 "Marejada sits in a corner, in silence. She doesn't look at the notebook."],
           opts: ["Read the page", "“What does it say, in a few words?”", "Ask Marejada what she thinks"] },
      pocas: { say: ["That the Singer didn't weep from sadness. She wept because they asked her to sing for ever and she said yes.",
                     "And that when she turned to stone, the lake saw again. One Tide stood still for ever so the others could have a tomorrow."] },
      madre: { say: ["I think my grandmothers knew and didn't say. Just as I didn't say about my mother's well.",
                     "We Tides keep secrets the way the lake keeps stones. At the bottom, where they don't bother anyone. And one day you realise the bottom is full and there's no water."] },
      leer: { say: ["The handwriting is very old, from another hand. “Three generations without seeing. Fish were born blind. One of us came, the one who sang best. She said: if someone has to stay, let it be someone who wants to.”",
                    "“She wept in the lake, because she was saying goodbye. Then she went up to the Heart and didn't come down. The lake saw that same night. We named the north shore after her. Then we forgot.”",
                    "The north shore's name is Orilla. Like me. My mother named me after one who turned to stone, and she didn't know."],
            opts: ["“All the Tides have to be told.”", "“That doesn't have to happen again.”", "Keep the page in your notebook"] },
      contar: { say: ["What for? So one of us volunteers? There are already girls who look at the Heart strangely since the statue business got out.",
                      "Tell it, daughter. But tell all of it. Let them see what it cost. Half a secret is worse than a whole one.",
                      "That night, on the shore, Orilla reads the page. The Tides listen. Nobody volunteers. But nobody leaves."] },
      repetir: { say: ["No? Then what? The lake stays blind for ever?",
                       "She thinks about it. She closes the notebook.",
                       "You're right about one thing. She chose. If anyone ever chooses, let it be because they want to, not because a notebook says so. I'll keep that."] },
      guardar: { say: ["You copy the page. Orilla watches you copy it.",
                       "Take it to the Heart, if you go. Let someone who isn't a Tide know what happened. That way forgetting it doesn't depend on us."] },
    } },

    "e2-espejo": { who: { marejada: "Mother Marejada" }, nodes: {
      a: { say: ["At midnight, the Mirror Lake reflects. Not the sky: something else. The Tides come out of their houses in silence and gather on the shore.",
                 "In the water you see a dark, enormous place, far below. Something sleeping curled up, like an animal in the cold. Around it, four stone figures with open hands. And among the four, a gap where there should be a fifth.",
                 "It's the Root's dream. It's dreaming it right now. And it's showing us."],
           opts: ["Look at the reflection for a long time", "Throw a stone into the water", "Ask Unísona to look", "“Nobody look. Let's go.”"] },
      mirar: { say: ["You look. The sleeping animal moves. It turns over. Along one side it has fine round wounds, like needle marks. From each wound a thread of light rises, upwards, towards the Meadow.",
                     "You count. Eleven wounds. Twelve. While you watch, another one opens.",
                     "Your eyes hurt. When you close them, you still see the wounds."] },
      piedra: { say: ["The stone breaks the reflection. The water moves, and for an instant the lake reflects the real sky: stars, clouds, the moon.",
                      "The Tides cry out with joy. Then the water settles, and the grey comes back. Neither dream nor sky.",
                      "You broke the only thing that was showing us anything. But we saw the sky. I don't know which is better."] },
      unisona: { say: ["Unísona looks at the reflection. It looks at the gap among the four statues. A long time.",
                       "Then it takes a step towards the water. Another. You have to grab it.",
                       "That gap is for someone who sings. It knows. Creatures that sing always know.",
                       "Unísona lets itself be taken home, but it keeps looking back until the lake goes dark."] },
      irse: { say: ["You're right. Some things shouldn't be seen twice.",
                    "The Tides go back to their houses. But that night, on the jetty, someone leaves a candle burning facing the water. And the next night, another."] },
    } },
  });

  add("caves", {
    "e2-sebo": { who: { sebo: "Sebo, the lamp keeper" }, nodes: {
      a: { say: ["At the entrance to the Hondura, the old lamp keeper is hanging oil lamps as always. But in the next gallery, the lamps are new: glass jars with something that glows by itself, no wick.",
                 "Sap. They fill them with sap that seeps from the tubes above. It shines brighter than my oil and never runs out. The Hondura is delighted.",
                 "I'm not. My lamps go out when the air runs short. That's how I know a gallery is bad. These never go out. With these you die in the light."],
           opts: ["“Has anyone fallen ill?”", "Swap the sap lamps for oil ones", "Buy him oil for the deep galleries", "Take a sap lamp to study it"] },
      enfermo: { say: ["Two diggers in gallery seven fell asleep working and didn't wake until the next day. With the lamp lit beside them, shining as if nothing were wrong.",
                       "With my lamps, the flame would have turned blue and small, and they'd have got out. The flame warns you. This light warns you of nothing."] },
      cambiar: { say: ["You spend the afternoon taking down jars and hanging oil lamps. The diggers complain: they give less light.",
                       "In gallery seven, the oil flame turns blue the moment you walk in. Everyone runs out. Nobody complains anymore.",
                       "See? The flame tells the truth. That's why they don't want it."] },
      aceite: { say: ["Sebo sells you oil at a friend's price. You fill the lamps in the deepest galleries.",
                      "It isn't much. But at least in those, if something goes wrong, someone will find out in time."] },
      llevar: { say: ["You take a jar of glowing sap. In the Ford, at night, it lights the whole room.",
                      "Your creatures sleep badly. Unísona covers it with a blanket. On the third day you take it back to the cave."] },
    } },

    "e2-sordina": { who: { sordina: "Sordina, pilgrim" }, nodes: {
      a: { say: ["In the Hall of Names, the pilgrim runs her fingers along the wall, letter by letter, as if reading blind.",
                 "They're fading. Look. I copied this name whole last year. Now it's missing two letters. This one, four. The stone is eating them.",
                 "The Hondura says it's the damp. I say the dead are leaving. If nobody answers them on the Night of the Echo, they get tired of waiting."],
           opts: ["“Did you copy the whole wall?”", "Help her go over the letters with a nail", "Read the names aloud, one by one", "“Maybe it's good that they leave.”"] },
      copio: { say: ["With you, remember? That notebook is the only thing still whole. I have it in my bag. It weighs like a stone.",
                     "But a name in a notebook isn't the same as a name in the Hall. In the Hall the echo repeats it. In the notebook only whoever opens it reads it."] },
      repasar: { say: ["You go over letters all night with nails. The stone is soft, too soft, like damp bread.",
                       "In the morning, the letters you went over are marked again. Deep. But the ones beside them, the ones you didn't touch, have faded a little more.",
                       "There isn't time. We're two and they're thousands. But these thirty stay another year."] },
      leer: { say: ["You read the names aloud. At first the Hall doesn't answer. After about a hundred, you hear something: not an echo. A sigh, very far away.",
                    "Sordina stops. She puts her hand on your arm.",
                    "Don't stop. They're listening. They don't answer, but they're listening.",
                    "You read until your voice gives out. One thousand two hundred names. When you finish, the Hall is just as quiet, but it no longer feels empty."] },
      bueno: { say: ["Good? Maybe. The dead have a right to rest from us too.",
                     "But if they all leave, the Hondura is left without a past. And a people without a past digs where it's told, because it doesn't remember why not to dig there."] },
    } },

    "e2-lindero": { who: { lindero: "Lindero, Albor surveyor" }, nodes: {
      a: { say: ["In a side gallery, the Albor surveyor is measuring the rock with a knotted cord. He no longer wears the Albor crest. He wears Destello's, sewn on top, crooked.",
                 "They changed my crest, my wages and my boss. The job's the same: measure how far you can dig without the roof coming down.",
                 "What I don't measure is how far you can dig without waking what's below. There's no cord for that."],
           opts: ["“You sold the old Hondura maps.”", "“How far do the Blind Wells go?”", "Take his new maps while he isn't looking", "“Stop measuring. Quit.”", "“Mark on the map the Line that mustn't be crossed.”"] },
      mapas: { say: ["Basalto sold them. I bought them. For Albor. Now Destello uses the same ones, with another seal. Maps don't know whose they are."] },
      llegan: { say: ["Deeper than Albor's. Much deeper. There's one, the one they call twelve, that goes down so far the cord doesn't reach. We had to tie three together.",
                      "At the bottom of twelve, the rock is warm and soft. It sinks when you touch it. And comes back. Like skin."] },
      robar: { say: ["When he turns round, you roll up the maps and put them away. It takes Lindero a while to notice.",
                     "My maps? Caretaker! Those maps are three months' work.",
                     "He doesn't chase you. He sits on a stone and stares at the knotted cord.",
                     "Take them. At least someone who doesn't dig has them."] },
      renunciar: { say: ["And have someone else measure, who knows less? Whoever comes after me won't stop anywhere. I at least stop where the stone moves.",
                         "He doesn't quit. But that week, in his report to Destello, well twelve appears as “unstable, do not continue”."] },
      linea: { say: ["Lindero looks at the map a long time. Then he takes out a piece of charcoal and draws a red line, horizontal, at a certain depth.",
                     "Here. Below this line, the rock stops being rock. Albor never went past it. Destello has already gone past it three times.",
                     "Take it. Show it to whoever you like. I've signed it. A surveyor who signs what isn't convenient loses his job, but keeps his name."] },
    } },

    "e2-pirita": { who: { pirita: "Pirita, digger", brida: "Brida, forewoman" }, nodes: {
      a: { say: ["At the mouth of the south tunnel, the Hondura digger and some thirty families have sat down on the ground, blocking the way. They have picks, but they rest them on their knees.",
                 "Nobody goes down today. Not from the Hondura, not from the Court, not from anywhere. Until they tell us what's down there.",
                 "On the other side, with her helmet and her board, Brida and Destello's forepeople wait. Behind them, a line of diggers with wooden tokens."],
           opts: ["Sit with Pirita", "Talk to Brida", "Show the maps of well twelve", "Persuade Pirita to let them through"] },
      brida: { say: ["She's right and I've got a line of people who don't eat if they don't go down. Both are true. That's what they don't understand up there.",
                     "If you give me a reason I can take to the matriarch, something you can touch, I'll tell her nobody goes down today. If not, I have to go through."] },
      sentar: { say: ["You sit on the ground, between Pirita and an old man of the Hondura. The forepeople hesitate.",
                      "You too, Caretaker?",
                      "Brida looks at the line of diggers. She looks at Pirita. She looks at the tunnel.",
                      "Nobody goes down today. Tomorrow, we'll see. Tomorrow is another day and another line."] },
      mapas: { say: ["You unroll the maps on the ground, between the two lines. Well twelve goes down and down. At the bottom, Lindero's hand: “the rock sinks and comes back”.",
                     "The diggers in the line come closer to look. Some leave. Brida holds the map for a long time.",
                     "This you can touch. I'll take it to her.",
                     "Take it. And tell her the Hondura doesn't go down twelve anymore. Not for double, not for triple."] },
      dejar: { say: ["Let them through? You? The one who took the Guardian's verse?",
                     "She looks at you with more sadness than anger.",
                     "Fine. Let them through. But let them walk over us, so it's seen.",
                     "Nobody walks over anybody. The diggers go home. So do the forepeople. Pirita stays sitting alone at the tunnel mouth until night."] },
    } },

    "e2-tunel9": { who: { brida: "Brida, forewoman", cavador: "Digger with black hands" }, nodes: {
      a: { say: ["Token in hand, you go in through the south tunnel. You go down a long way. The air turns warm, then hot, then damp like someone's breath.",
                 "In tunnel nine, the walls have veins. Real veins, that beat. A digger is sitting against the wall, his hands black up to the elbows. He doesn't move.",
                 "Don't touch me. It sticks. I can't feel my fingers anymore. But I keep digging. They pay by the day."],
           opts: ["“How long have you been here?”", "Carry him out on your back", "Look for Grieto among the diggers", "Put your hand on the wall"] },
      cuanto: { say: ["Three weeks. I came down with House Alba's carts. They told me Hollow and brought me here.",
                      "At first it was just the heat. Then the walls started to move. Then the hands. Brida knows. Brida moved me to three, but I went back to nine, because nine pays more."] },
      sacar: { say: ["You hoist him onto your back. He weighs little: he's thin as a stick. His black hands stain your neck and it burns, cold.",
                     "On the way up you meet Brida coming down with an oil lamp. The flame is blue.",
                     "Give him to me. I'll get him out. You go back up and tell whoever you like what you saw. I don't care who anymore."] },
      grieto: { say: ["You ask for Grieto. A thin boy, with the grey ribbon still sewn on his coat, raises his head at the far end of the gallery.",
                      "That's him. The one from the bridge house. He cries at night. We all cry at night, but with him you notice.",
                      "You give him the letter. He reads it. He reads it again. He drops his pick.",
                      "“My mum keeps my bed made,” he says. And he comes up with you, without asking anyone's leave."] },
      pared: { say: ["You put your hand on it. The wall is soft and warm and it moves, up and down, slowly. It breathes.",
                     "And for a moment, in your palm, you feel something else: a tremor, like someone who's cold. Or afraid.",
                     "You pull your hand away. It leaves a black print that takes three days to fade."] },
    } },

    "e2-derrumbe": { who: { basalto: "First Pick Basalto", pirita: "Pirita, digger" }, nodes: {
      a: { say: ["The First Pick takes you to an old gallery, from before the maps. In his hand is a pick nobody has used for fifty years: the cave-in pick.",
                 "From here you reach the new tunnels from below. If I strike in the right place, it all comes down. The Blind Wells, the tubes, everything.",
                 "And half the old Hondura too, with the Hall of Names. The stone doesn't choose whose tomb."],
           opts: ["“And the people working down there?”", "“Do it.”", "“No. There's another way.”", "Sing Grava's verse before deciding"] },
      gente: { say: ["We'd warn them. One night. With Sebo's lamps, the ones that turn blue. Whoever wants to get out, gets out.",
                     "Whoever doesn't… Caretaker, I sold the maps. Every cave-in I don't make is another day someone goes down by my maps. I don't know which of the two is killing me more."] },
      hacer: { say: ["Wait! The Hall. My father is on that wall.",
                     "Basalto stops with the pick raised.",
                     "Your father is in Sordina's notebook too, digger. The dead can live on paper. The living down there can't.",
                     "Pirita cries. But she doesn't stop him. That night, the Hondura's oil lamps turn blue one by one, and people get out. At dawn, Basalto strikes.",
                     "The noise is heard as far as the Meadow. Half the Hondura comes down. The new tunnels too. In the Dim Quarter, two streets go dark."] },
      no: { say: ["Another way? Tell me. I've been looking for it for a year.",
                  "You don't have a whole one. You have pieces: a map, a letter, a tube that sings, an old woman who remembers a verse.",
                  "Pieces. Fine. My people made the Hall out of pieces of names. Let's try your pieces. If they fail, the pick is still here."] },
      grava: { say: ["You sing what Grava sang with you. The old gallery answers. Not one word: the whole verse, faint, as if from very far away.",
                     "“I will sleep as long as no one drinks beneath my dreams.”",
                     "She knew. The Guardian. A hundred years repeating the only thing that mattered, and we thought she was mad.",
                     "I won't bring anything down. If the Root asks that no one drink, what has to be done is that no one drinks. Not bury the ones who drink.",
                     "He leaves the pick in the rock. That night, the whole Hondura goes with him to the south tunnel, two stones each, to strike the walls of the Blind Wells until the diggers come out to see what's happening."] },
    } },

    "e2-eco": { who: { pirita: "Pirita, digger", sordina: "Sordina, pilgrim" }, nodes: {
      a: { say: ["It's the Night of the Echo again. The Hondura families strike two stones in the Hall and say the names of their dead. This time with less hope than last year.",
                 "Dad.",
                 "A second of silence. Then, from the far end of the Hall, faint, hoarse: “…Dad…”. It's nobody's voice. It's the stone repeating. But it repeats."],
           opts: ["Strike stones yourself and say a name", "Look at Pirita", "Ask Sordina what changed"] },
      pirita: { say: ["Pirita holds the two stones tight in her hands and can't go on. She's crying and laughing at once.",
                      "It answered me. Well, the Hall answered. But it's the same. My dad said the Hall and the dead were the same thing."] },
      cambio: { say: ["Something up above stopped drinking, even a little. The stone is less soft. When the stone is hard, the echo comes back.",
                      "It isn't that the dead have come back. It's that the stone remembers how to repeat again. For us it's the same."] },
      golpear: { say: ["You strike two stones. You say a name. Someone you lost, or someone who taught you something. It doesn't matter which.",
                       "The Hall takes its time. Then it repeats it, softly, warped, but whole.",
                       "The Hondura families turn to look at you. Someone passes you two more stones. You stay all night, striking with them."],
                 opts: ["Stay until the end", "Carry the echo to the Heart, in your memory"] },
      final: { say: ["Near dawn, Pirita says the last name. The Hall repeats it. Then, for the first time in two years, the Hall says something nobody said: “…thank you…”.",
                     "Nobody knows who said it first. Maybe nobody. Maybe the stone.",
                     "If we have to go to the Heart, the Hondura goes. With all our dead behind us."] },
      llevar: { say: ["Take it. And if one day you sing in the Heart, strike two stones first. The Root remembers us by that sound.",
                      "She gives you two flat stones from the Hall, worn by years of striking."] },
    } },

    "e2-sebo2": { who: { sebo: "Sebo, the lamp keeper", brida: "Brida, forewoman" }, nodes: {
      a: { say: ["The old lamp keeper and the forewoman in the helmet are sitting at the Hondura entrance, sharing an oil lamp and a bottle. They look like two people who fought for a long time and have no energy left for it.",
                 "He told me about the blue flame. I asked him for lamps for the Blind Wells. He said no.",
                 "I told her I won't sell them to her. I'll give them. If the matriarch wants lamps that warn, let her not pay. That way she owes nobody anything when they tell her the truth."],
           opts: ["“Will the matriarch let them use them?”", "Help carry the lamps to the Wells", "“Brida, what will you do if the flame turns blue?”"] },
      dejar: { say: ["I won't ask her. I'll hang them and that's that. If she asks, I'll tell her oil is cheaper.",
                     "It's the second time I've lied to her. The first cost me a sleepless night. This one, none. That scares me more."] },
      cargar: { say: ["You carry forty lamps down the south tunnel. You hang them in every gallery of the Blind Wells.",
                      "In gallery twelve, every flame turns blue at once. The diggers look at each other. One drops his pick and climbs out. Another. Then all of them.",
                      "The flame doesn't lie. That's why I love it so."] },
      azul: { say: ["Get them out. All of them. Even if it costs me my name.",
                    "The matriarch asked me what my name was. She was the first. But a name you earn by sending people to die isn't a name, Caretaker. It's a token with letters on it.",
                    "Sebo passes her the bottle. She drinks. Then she puts a hand on the old man's shoulder, awkwardly, like someone who never does that."] },
    } },
  });
})(window.EVEVENTS_EN);
